    /// The window on `yard` with its settings kept in `file`, the focus in
    /// the line, once the yardmaster's conversation shows.
    fn opened_kept<'a>(
        yard: &Yard,
        file: &std::path::Path,
        cx: &'a mut TestAppContext,
    ) -> (Entity<Footplate>, &'a mut VisualTestContext) {
        let (client, file) = (yard.client(), file.to_path_buf());
        let (view, cx) = cx.add_window_view(|window, cx| {
            let view = Footplate::new(client, "jo".into(), window, cx).kept_in(Some(file), cx);
            window.focus(&view.line.focus_handle(cx));
            view
        });
        wait(cx, "the yardmaster's conversation", |cx| {
            texts(&view, cx) == ["Shall I land it?"]
        });
        (view, cx)
    }

    #[gpui::test]
    fn closing_the_window_hides_on_a_mac_while_the_menu_bar_item_is_on_and_else_closes(
        cx: &mut TestAppContext,
    ) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        cx.update(|cx| {
            input::bind_keys(cx);
            bind_keys(cx);
        });
        let (view, cx) = opened_kept(&yard, &file, cx);
        let mac = cfg!(target_os = "macos");

        // Nobody chose: the item is on. On a Mac the close button is
        // refused, and the window with all it holds stays (hidden, which a
        // test does not do); elsewhere it closes, as it always did.
        assert!(settings_of(&view, cx).menu_bar);
        assert_eq!(cx.simulate_close(), !mac);
        assert_eq!(texts(&view, cx), ["Shall I land it?"]);

        // The switch is there on every system, for the menu bar's item
        // or the tray's. Switched off, it is kept, and closing closes: the
        // application then quits with its one window. A tall window, so
        // the switch at the pane's end is above the fold.
        cx.simulate_resize(gpui::size(px(1600.), px(1400.)));
        cx.simulate_keystrokes("secondary-,");
        click_on(cx, "menu bar off");
        assert!(!settings_of(&view, cx).menu_bar);
        assert!(!Settings::read(&file).menu_bar);
        // On again, closing hides again, on a Mac alone.
        click_on(cx, "menu bar on");
        assert!(Settings::read(&file).menu_bar);
        assert_eq!(cx.simulate_close(), !mac);
        // Off, however it came to be, closing closes on every system.
        view.update(cx, |v, cx| v.menu_bar_on(false, cx));
        assert!(cx.simulate_close());
    }

    fn settings_of(view: &Entity<Footplate>, cx: &mut VisualTestContext) -> Settings {
        view.read_with(cx, |v, _| v.settings.clone())
    }

    /// The shown yard's entry of the settings, as listed.
    fn entry_of(view: &Entity<Footplate>, cx: &mut VisualTestContext) -> settings::Yard {
        view.read_with(cx, |v, _| v.settings.yard(&v.yard).cloned().unwrap())
    }

    /// The shown yard's web view set to `base`: what a test sets where
    /// the window's view address is wanted up or down.
    fn set_view(view: &Entity<Footplate>, cx: &mut VisualTestContext, base: &str) {
        view.update(cx, |v, cx| {
            let yard = v.yard.clone();
            v.set(v.settings.clone().with_yard_view(&yard, base).unwrap(), cx);
        });
    }

    /// The shown yard's run base set to `base`.
    fn set_run(view: &Entity<Footplate>, cx: &mut VisualTestContext, base: &str) {
        view.update(cx, |v, cx| {
            let yard = v.yard.clone();
            v.set(v.settings.clone().with_yard_run(&yard, base).unwrap(), cx);
        });
    }

    /// What "Agents and you" holds of the line about the operator, and
    /// what came of its last read or save.
    fn agents_about(view: &Entity<Footplate>, cx: &mut VisualTestContext) -> String {
        view.read_with(cx, |v, cx| v.agents_about.read(cx).text().to_string())
    }

    fn agents_said(view: &Entity<Footplate>, cx: &mut VisualTestContext) -> String {
        view.read_with(cx, |v, _| v.agents_said.clone().unwrap_or_default())
    }

    fn settings_open(view: &Entity<Footplate>, cx: &mut VisualTestContext) -> bool {
        view.read_with(cx, |v, _| v.settings_open)
    }

    /// The colours the window is drawn in, the line and the messages too.
    fn palette(cx: &mut VisualTestContext) -> Palette {
        cx.run_until_parked();
        cx.update(|window, cx| Palette::now(window, cx))
    }

    #[gpui::test]
    fn the_settings_change_the_window_at_once_and_are_kept(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        cx.update(|cx| {
            input::bind_keys(cx);
            bind_keys(cx);
        });
        let (view, cx) = opened_kept(&yard, &file, cx);
        // The first read keeps a watermark as well as today's look.
        let today = Settings {
            text: 14,
            look: Look::Auto,
            ..Settings::default().with_timetable_seen("this machine", 20)
        };
        assert_eq!(settings_of(&view, cx), today);
        let desktop = cx.update(|window, _| window.appearance());
        assert_eq!(palette(cx), Palette::of(Look::Auto, desktop));
        assert_eq!(cx.update(|window, _| window.rem_size()), px(16.));
        assert_eq!(Settings::read(&file), today);

        // One key shows the settings where the conversation was. What is
        // typed then is not for the line, which is out of view.
        cx.simulate_input("hal");
        cx.simulate_keystrokes("secondary-,");
        assert!(settings_open(&view, cx));
        assert!(drawn(cx, "text size"));
        assert!(drawn(cx, "look auto"));
        cx.simulate_input("x");
        assert_eq!(typed(&view, cx), "hal");
        // The settings have no text of their own to type: shift and Enter
        // break no line there, and Enter sends nothing.
        cx.simulate_keystrokes("shift-enter enter");
        assert_eq!(typed(&view, cx), "hal");
        assert_eq!(yard.asked("Mail"), Vec::<serde_json::Value>::new());

        // Larger and smaller by a key each: the whole window at once, by
        // its rem, and the file has it.
        cx.simulate_keystrokes("secondary-= secondary-=");
        assert_eq!(settings_of(&view, cx).text, 16);
        cx.run_until_parked();
        cx.update(|window, _| window.refresh());
        cx.run_until_parked();
        assert_eq!(
            cx.update(|window, _| window.rem_size()),
            px(16. * 16. / 14.)
        );
        assert_eq!(Settings::read(&file).text, 16);
        cx.simulate_keystrokes("secondary--");
        assert_eq!(settings_of(&view, cx).text, 15);
        cx.simulate_keystrokes("secondary-0");
        assert_eq!(settings_of(&view, cx).text, 14);
        assert_eq!(Settings::read(&file), today);
        // And by the buttons.
        click_on(cx, "text larger");
        click_on(cx, "text larger");
        click_on(cx, "text smaller");
        assert_eq!(settings_of(&view, cx).text, 15);
        click_on(cx, "text usual");
        assert_eq!(settings_of(&view, cx).text, 14);
        // The ends hold.
        for _ in 0..12 {
            cx.simulate_keystrokes("secondary-=");
        }
        assert_eq!(settings_of(&view, cx).text, settings::TEXT_MAX);
        for _ in 0..12 {
            cx.simulate_keystrokes("secondary--");
        }
        assert_eq!(settings_of(&view, cx).text, settings::TEXT_MIN);
        assert_eq!(Settings::read(&file).text, settings::TEXT_MIN);

        // The look: one key steps through them, a button chooses one, and
        // the window is drawn in it at once, whatever the desktop has.
        cx.simulate_keystrokes("secondary-shift-l");
        assert_eq!(settings_of(&view, cx).look, Look::Light);
        assert_eq!(palette(cx), Palette::of(Look::Light, desktop));
        cx.simulate_keystrokes("secondary-shift-l");
        assert_eq!(settings_of(&view, cx).look, Look::Dark);
        assert_eq!(
            palette(cx),
            Palette::of(Look::Dark, WindowAppearance::Light)
        );
        cx.simulate_keystrokes("secondary-shift-l");
        assert_eq!(settings_of(&view, cx).look, Look::Auto);
        click_on(cx, "look light");
        assert_eq!(settings_of(&view, cx).look, Look::Light);
        click_on(cx, "look dark");
        assert_eq!(
            palette(cx),
            Palette::of(Look::Dark, WindowAppearance::Light)
        );
        let set = Settings {
            text: settings::TEXT_MIN,
            look: Look::Dark,
            ..Settings::default().with_timetable_seen("this machine", 20)
        };
        assert_eq!(Settings::read(&file), set);
        assert_eq!(view.read_with(cx, |v, _| v.unkept.clone()), None);

        // Esc goes back to the conversation, and the line has the keys.
        cx.simulate_keystrokes("escape");
        assert!(!settings_open(&view, cx));
        cx.simulate_input("t");
        assert_eq!(typed(&view, cx), "halt");
        // The rail's gear opens them and shuts them; so does the
        // back button, and a row that is opened.
        click_on(cx, "settings");
        assert!(settings_open(&view, cx));
        click_on(cx, "settings");
        assert!(!settings_open(&view, cx));
        click_on(cx, "settings");
        click_on(cx, "settings back");
        assert!(!settings_open(&view, cx));
        cx.simulate_keystrokes("secondary-,");
        cx.simulate_keystrokes("tab");
        assert!(!settings_open(&view, cx));
        // The keys of their own work with the settings shut too.
        cx.simulate_keystrokes("secondary-=");
        assert_eq!(settings_of(&view, cx).text, settings::TEXT_MIN + 1);

        // A restart: the next window is as this one was left.
        let left = settings_of(&view, cx);
        let (again, cx) = opened_kept(&yard, &file, cx);
        assert_eq!(settings_of(&again, cx), left);
        assert_eq!(left.look, Look::Dark);
        assert_eq!(
            palette(cx),
            Palette::of(Look::Dark, WindowAppearance::Light)
        );
        cx.update(|window, _| window.refresh());
        cx.run_until_parked();
        assert_eq!(cx.update(|window, _| window.rem_size()), left.rem());
    }

    /// A file that cannot be written keeps nothing, and says so; the window
    /// has the change all the same.
    #[gpui::test]
    fn a_change_that_cannot_be_kept_is_said_and_still_drawn(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let in_the_way = dir.path().join("footplate");
        std::fs::write(&in_the_way, "a file where the directory would be").unwrap();
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        cx.update(|cx| {
            input::bind_keys(cx);
            bind_keys(cx);
        });
        let (view, cx) = opened_kept(&yard, &in_the_way.join("settings.json"), cx);
        assert_eq!(
            settings_of(&view, cx),
            Settings::default().with_timetable_seen("this machine", 20)
        );
        cx.simulate_keystrokes("secondary-=");
        assert_eq!(settings_of(&view, cx).text, 15);
        assert!(view.read_with(cx, |v, _| v.unkept.is_some()));
    }

    #[gpui::test]
    fn the_web_view_s_address_is_kept_from_the_settings(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        cx.update(|cx| {
            input::bind_keys(cx);
            bind_keys(cx);
        });
        let (view, cx) = opened_kept(&yard, &file, cx);
        // The field holds nothing, from the file that keeps nothing of
        // the yard's: its view is the usual address.
        assert_eq!(entry_of(&view, cx).web_view, "");
        assert_eq!(
            view.read_with(cx, |v, _| v.view_base()),
            Some(settings::WEB_VIEW.to_string())
        );
        cx.simulate_keystrokes("secondary-,");
        assert!(settings_open(&view, cx));
        click_on(cx, "settings section connection");
        assert!(drawn(cx, "view address"));
        // What is no address is said, and nothing changed.
        view.update(cx, |v, cx| {
            v.view.update(cx, |line, cx| line.set_text("plantime", cx))
        });
        click_on(cx, "view save");
        assert_eq!(entry_of(&view, cx).web_view, "");
        assert!(drawn(cx, "view said"));
        // The usual address clears an unsaved invalid value too, even
        // though the stored setting was already unset.
        click_on(cx, "view usual");
        assert_eq!(
            view.read_with(cx, |v, cx| v.view.read(cx).text().to_string()),
            ""
        );
        assert_eq!(view.read_with(cx, |v, _| v.view_said.clone()), None);
        // Kept, it is the yard's, and the file has it on its entry.
        let base = view_up();
        view.update(cx, |v, cx| {
            v.view.update(cx, |line, cx| line.set_text(&base, cx))
        });
        click_on(cx, "view save");
        assert_eq!(entry_of(&view, cx).web_view, base);
        assert_eq!(
            Settings::read(&file).yard(settings::HERE).unwrap().web_view,
            base
        );
        // Said no longer: the test frame's bounds only ever grow, so
        // what is gone is read, not drawn.
        assert_eq!(view.read_with(cx, |v, _| v.view_said.clone()), None);
        wait(cx, "the web view", |cx| {
            view_answered(&view, cx) == Some(true)
        });
        // The usual address unsets it again: the yard's usual.
        click_on(cx, "view usual");
        assert_eq!(entry_of(&view, cx).web_view, "");
        assert_eq!(
            Settings::read(&file).yard(settings::HERE).unwrap().web_view,
            ""
        );
        assert_eq!(
            view.read_with(cx, |v, _| v.view_base()),
            Some(settings::WEB_VIEW.to_string())
        );
    }

