    /// "Agents and you" reads the near yard's operator settings: the style
    /// the yard has, and the line. Saving sets the chosen style and the
    /// line about the operator, and says the next session picks it up;
    /// an emptied line unsets the note.
    #[gpui::test]
    fn agents_and_you_reads_and_saves_the_operator_s_settings(cx: &mut TestAppContext) {
        use crate::setup::standin;

        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        cx.update(|cx| {
            input::bind_keys(cx);
            bind_keys(cx);
        });
        let (view, cx) = opened_kept(&yard, &file, cx);
        // The section shows alone: the window is tall enough to hold it,
        // so its buttons take clicks.
        cx.simulate_resize(gpui::size(px(1200.), px(1800.)));
        let (means, program, _) = stand_in_means(dir.path(), false);
        standin::answers(&program, "doctor", 0, &standin::doctor_ready());
        standin::answers(&program, "status", 0, &standin::status(true, false));
        standin::answers(
            &program,
            "settings-get",
            0,
            &json!([
                {"key": "operator_style", "value": "work", "from": "set"},
                {"key": "operator_note", "value": "I read code", "from": "set"},
            ]),
        );
        standin::answers(&program, "settings-set", 0, &json!({}));
        view.update(cx, |v, _| v.means = means);
        view.update(cx, |v, cx| v.refresh_switch(cx));
        wait(cx, "the switch read", |cx| {
            settled(&view, cx) && view.read_with(cx, |v, _| v.switch_status.is_some())
        });

        // Opening the settings reads the pair: the style chosen, and the
        // line in the field.
        cx.simulate_keystrokes("secondary-,");
        assert!(settings_open(&view, cx));
        click_on(cx, "settings section agents");
        wait(cx, "the operator's settings read", |cx| {
            view.read_with(cx, |v, _| v.agents_read)
        });
        assert_eq!(view.read_with(cx, |v, _| v.agents_style), 2);
        assert_eq!(agents_about(&view, cx), "I read code");
        for key in ["guide", "show", "work", "report"] {
            assert!(drawn(cx, &format!("agents style {key}")), "{key}");
        }
        assert!(drawn(cx, "agents about") && drawn(cx, "agents save"));

        // Another style and another line are the two commands, and the
        // next session picks them up.
        click_on(cx, "agents style report");
        view.update(cx, |v, cx| {
            v.agents_about.update(cx, |line, cx| {
                line.set_text("I review every merge myself", cx)
            })
        });
        let calls = standin::calls(&program).len();
        click_on(cx, "agents save");
        wait(cx, "the save", |cx| {
            agents_said(&view, cx) == "Saved. The next session picks it up."
        });
        assert_eq!(
            standin::calls(&program)[calls..],
            [
                "[settings] [set] [--json] [--] [operator_style] [report]".to_string(),
                "[settings] [set] [--json] [--] [operator_note] [I review every merge myself]"
                    .to_string(),
            ]
        );

        // An emptied line unsets the note; the style is set as chosen.
        view.update(cx, |v, cx| {
            v.agents_about.update(cx, |line, cx| line.set_text("", cx))
        });
        let calls = standin::calls(&program).len();
        click_on(cx, "agents save");
        wait(cx, "the unset", |_| {
            standin::calls(&program).len() == calls + 2
        });
        assert_eq!(
            standin::calls(&program)[calls..],
            [
                "[settings] [set] [--json] [--] [operator_style] [report]".to_string(),
                "[settings] [set] [--json] [--] [operator_note] []".to_string(),
            ]
        );
    }

    /// "Agents and you" at an address is read-only: the section says the
    /// settings are the operator's at that machine, and nothing of yardr's
    /// runs for it.
    #[gpui::test]
    fn agents_and_you_at_an_address_is_read_only(cx: &mut TestAppContext) {
        use crate::setup::standin;

        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        Settings {
            yards: vec![settings::Yard::far(
                "remote",
                "https://yard.example.net",
                "remote.token",
            )],
            open: "remote".to_string(),
            ..Settings::default()
        }
        .write(&file)
        .unwrap();
        let env = Env {
            socket: dir.path().join("yard.sock"),
            ..Env::default()
        };
        let (view, cx) = opened_at(env, &file, cx);
        let (means, program, _) = stand_in_means(dir.path(), true);
        view.update(cx, |v, _| v.means = means);
        view.update(cx, |v, cx| v.refresh_switch(cx));
        wait(cx, "the yard away", |cx| {
            settled(&view, cx) && view.read_with(cx, |v, _| v.down.is_some())
        });
        click_on(cx, "settings");
        assert!(settings_open(&view, cx));
        click_on(cx, "settings section agents");
        assert!(drawn(cx, "agents far"));
        assert!(!drawn(cx, "agents save") && !drawn(cx, "agents about"));
        assert!(!drawn(cx, "agents style guide"));
        assert!(!view.read_with(cx, |v, _| v.agents_read));
        assert!(standin::calls(&program).is_empty());
    }

    /// With the yard away the left column has its head and its foot: the
    /// settings are reached by the same key, and by the control there.
    #[gpui::test]
    fn the_settings_are_reached_while_the_yard_is_away(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let socket = dir.path().join("yard.sock");
        cx.update(|cx| {
            input::bind_keys(cx);
            bind_keys(cx);
        });
        let (view, cx) = cx.add_window_view(|window, cx| {
            let view = Footplate::new(Client::new(&socket), "jo".into(), window, cx);
            window.focus(&view.line.focus_handle(cx));
            view
        });
        wait(cx, "that there is no yard", |cx| {
            view.read_with(cx, |v, _| {
                v.down
                    .as_deref()
                    .is_some_and(|why| why.starts_with("No yard"))
            })
        });
        cx.simulate_keystrokes("secondary-,");
        assert!(settings_open(&view, cx));
        assert!(drawn(cx, "look auto"));
        cx.simulate_keystrokes("secondary-shift-l secondary-=");
        assert_eq!(
            settings_of(&view, cx),
            Settings {
                text: 15,
                look: Look::Light,
                ..Settings::default()
            }
        );
        cx.simulate_keystrokes("escape");
        assert!(!settings_open(&view, cx));
        click_on(cx, "settings");
        assert!(settings_open(&view, cx));
        click_on(cx, "settings back");
        assert!(!settings_open(&view, cx));
    }

    /// The settings show one section, picked from the side list: each
    /// section shows its controls, and the open section is kept.
    #[gpui::test]
    fn the_settings_show_one_section_picked_from_the_side_list(cx: &mut TestAppContext) {
        use crate::setup::standin;

        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        cx.update(|cx| {
            input::bind_keys(cx);
            bind_keys(cx);
        });
        let (view, cx) = opened_kept(&yard, &file, cx);
        // The login switch and "Agents and you" read yardr's answers.
        let (means, program, _) = stand_in_means(dir.path(), false);
        standin::answers(&program, "doctor", 0, &standin::doctor_ready());
        standin::answers(&program, "status", 0, &standin::status(true, false));
        standin::answers(
            &program,
            "settings-get",
            0,
            &json!([
                {"key": "operator_style", "value": "work", "from": "set"},
                {"key": "operator_note", "value": "I read code", "from": "set"},
            ]),
        );
        view.update(cx, |v, _| v.means = means);
        view.update(cx, |v, cx| v.refresh_switch(cx));
        wait(cx, "the switch read", |cx| {
            settled(&view, cx) && view.read_with(cx, |v, _| v.switch_status.is_some())
        });

        cx.simulate_keystrokes("secondary-,");
        assert!(settings_open(&view, cx));
        // Appearance opens, and alone: the window's look and text size,
        // its item and the item's mark.
        for section in Section::ALL {
            assert!(
                drawn(cx, &format!("settings section {}", section.name())),
                "{}",
                section.name()
            );
        }
        assert!(drawn(cx, "text size"));
        assert!(drawn(cx, "look auto"));
        assert!(drawn(cx, "menu bar on"));
        assert!(drawn(cx, "tray auto"));
        assert!(!drawn(cx, "add near"));
        assert!(!drawn(cx, "agents save"));
        assert!(!drawn(cx, "notify on"));
        assert!(!drawn(cx, "view address"));
        // Yards: the list with its buttons, and the open yard's start at
        // login.
        click_on(cx, "settings section yards");
        assert!(drawn(cx, "yard row this machine"));
        assert!(drawn(cx, "add near") && drawn(cx, "add far") && drawn(cx, "add hosted"));
        assert!(drawn(cx, "login off") && drawn(cx, "login on"));
        // Agents: the operator's styles, the line about them, and save.
        click_on(cx, "settings section agents");
        wait(cx, "the operator's settings read", |cx| {
            view.read_with(cx, |v, _| v.agents_read)
        });
        assert!(drawn(cx, "agents style work"));
        assert!(drawn(cx, "agents about") && drawn(cx, "agents save"));
        // Crew: one row each, with what it is doing.
        click_on(cx, "settings section crew");
        wait(cx, "the crew read", |cx| {
            view.read_with(cx, |v, _| v.crew_read)
        });
        assert!(drawn(cx, "crew row assembly"));
        assert!(drawn(cx, "crew row yardmaster"));
        assert_eq!(
            view.read_with(cx, |v, _| v
                .crew
                .iter()
                .map(|member| (member.name.clone(), model::state_of(member).to_string()))
                .collect::<Vec<_>>()),
            [
                ("assembly".to_string(), "not running".to_string()),
                ("yardmaster".to_string(), "idle".to_string()),
            ]
        );
        // Notifications: the switch. Switching it on asks the system,
        // which the notification tests stand in for.
        click_on(cx, "settings section notifications");
        assert!(drawn(cx, "notify off") && drawn(cx, "notify on"));
        // Connection: the web view's address and the run base.
        click_on(cx, "settings section connection");
        assert!(drawn(cx, "view address") && drawn(cx, "run address"));

        // The open section is kept: closing and opening shows it still,
        // and so does a restart.
        click_on(cx, "settings section crew");
        assert_eq!(settings_of(&view, cx).section, Section::Crew);
        assert_eq!(Settings::read(&file).section, Section::Crew);
        cx.simulate_keystrokes("escape");
        assert!(!settings_open(&view, cx));
        cx.simulate_keystrokes("secondary-,");
        assert!(settings_open(&view, cx));
        assert!(drawn(cx, "crew row yardmaster"));
        let (again, cx) = opened_kept(&yard, &file, cx);
        assert_eq!(settings_of(&again, cx).section, Section::Crew);
        cx.simulate_keystrokes("secondary-,");
        assert!(settings_open(&again, cx));
        wait(cx, "the crew read again", |cx| {
            again.read_with(cx, |v, _| v.crew_read)
        });
        assert!(drawn(cx, "crew row assembly"));
        // Back to the first, the file says nothing of the section.
        click_on(cx, "settings section appearance");
        assert!(drawn(cx, "text size"));
        assert!(!std::fs::read_to_string(&file).unwrap().contains("section"));
    }

    /// The layout at the smallest and the largest text: the rows of the
    /// left column stand under one another, a long head still ends before
    /// the bead's id (which is why it ends in an ellipsis, footplate-eryf),
    /// the column and its rows go with the text, and the rail stays 56
    /// pixels wide with its 32-pixel targets.
    #[gpui::test]
    fn the_layout_holds_at_the_smallest_and_the_largest_text(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer(
            "UserAsks",
            &json!({"result": {"open": [
                {"bead": "bead-a", "bead_title": "Move the links", "topic": "topic:linear-out",
                 "ask": 3, "question": "A deliberately long question that must be cut before the id", "asker": "yardmaster",
                 "since": "2026-10-10T10:00:00Z"},
                {"bead": "bead-b", "bead_title": "Short", "topic": "topic:linear-out",
                 "ask": 4, "question": "Name it?", "asker": "yardmaster",
                 "since": "2026-10-10T11:00:00Z"}
            ], "decided": []}})
            .to_string(),
        );
        yard.answer("Bead", &bead_three());
        cx.update(|cx| {
            input::bind_keys(cx);
            bind_keys(cx);
        });
        let (view, cx) = cx.add_window_view(|window, cx| {
            let view = Footplate::new(yard.client(), "jo".into(), window, cx);
            window.focus(&view.line.focus_handle(cx));
            view
        });
        wait(cx, "the decisions", |cx| {
            to_decisions(&view, cx);
            view.read_with(cx, |v, _| {
                v.model.as_ref().is_some_and(|m| m.decisions_count() == 2)
            })
        });
        wait(cx, "the bead", |cx| has_bead(&view, cx, "bead-a"));

        let mut rows = Vec::new();
        for text in [settings::TEXT_MIN, settings::TEXT, settings::TEXT_MAX] {
            view.update(cx, |v, cx| {
                let set = Settings {
                    text,
                    ..v.settings.clone()
                };
                v.set(set, cx)
            });
            let rem = settings_of(&view, cx).rem();
            let first = bounds_of(cx, "decision row bead-a");
            let second = bounds_of(cx, "decision row bead-b");
            let long = bounds_of(cx, "decision head bead-a");
            let short = bounds_of(cx, "decision head bead-b");
            let id = bounds_of(cx, "decision id bead-a");
            assert!(
                first.bottom() <= second.top(),
                "at {text} px a row overlaps the next: {first:?} {second:?}"
            );
            assert!(
                first.top() <= long.top() && long.bottom() <= first.bottom(),
                "at {text} px the head leaves its row: {long:?} {first:?}"
            );
            assert!(
                long.right() < id.left() && id.right() <= first.right(),
                "at {text} px the long head touches the id: {long:?} {id:?}"
            );
            assert_eq!(
                short.size.width, long.size.width,
                "at {text} px the head's column hugs its content"
            );
            // The rail stays 56 pixels wide with its 40-pixel targets,
            // whatever the text.
            let rail = bounds_of(cx, "rail");
            assert!(
                (rail.size.width - px(56.)).abs() < px(1.),
                "at {text} px the rail is {rail:?}, not 56 wide"
            );
            for target in ["rail mark", "rail chat", "switch tile", "settings"] {
                let at = bounds_of(cx, target);
                assert!(
                    (at.size.width - px(40.)).abs() < px(1.)
                        && (at.size.height - px(40.)).abs() < px(1.),
                    "at {text} px {target} is {at:?}, not 40 a side"
                );
                assert!(
                    rail.left() <= at.left() && at.right() <= rail.right() + px(1.),
                    "at {text} px {target} leaves the rail: {at:?} {rail:?}"
                );
            }
            assert!(
                rail.right() <= first.left() + rem,
                "at {text} px the column leaves the rail: {rail:?} {first:?}"
            );
            rows.push((first.size.width, first.size.height, long.size.height));
        }
        // Smaller and larger than the usual in every measure.
        assert!(rows[0].0 < rows[1].0 && rows[1].0 < rows[2].0, "{rows:?}");
        assert!(rows[0].1 < rows[1].1 && rows[1].1 < rows[2].1, "{rows:?}");
        assert!(rows[0].2 < rows[1].2 && rows[1].2 < rows[2].2, "{rows:?}");
        let rail = bounds_of(cx, "rail");
        assert!((rail.size.width - px(56.)).abs() < px(1.));
    }

    /// A section's head says what waits in it: the number with its
    /// words, or that none does. The Crew head says unread, a platform
    /// arriving, the folded Decided decided.
    #[test]
    fn a_section_s_head_counts_what_waits_in_it() {
        assert_eq!(waiting_words(0), "none waiting");
        assert_eq!(waiting_words(1), "1 waiting");
        assert_eq!(waiting_words(12), "12 waiting");
        assert_eq!(unread_words(0), "none unread");
        assert_eq!(unread_words(1), "1 unread");
        assert_eq!(unread_words(12), "12 unread");
        assert_eq!(arriving_words(1), "1 arriving");
        assert_eq!(arriving_words(3), "3 arriving");
        assert_eq!(decided_words(1), "1 decided");
        assert_eq!(decided_words(3), "3 decided");
    }

    /// Each mode's list stands under its title with its count at the
    /// right: "Decisions" over the open questions, "Crew" over the
    /// conversations, "Timetable" over the arrivals row. Each head stands
    /// whatever the yard holds, in its own mode alone. What was drawn
    /// stays drawn to the tests, so a head's absence is said only where
    /// it was never drawn: the window opens in decisions, and the other
    /// heads are said away there.
    #[gpui::test]
    fn the_sections_stand_under_their_titles_with_their_counts(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer(
            "UserAsks",
            &json!({"result": {"open": [
                {"bead": "bead-a", "bead_title": "Move the links", "topic": "topic:linear-out",
                 "ask": 3, "question": "Move them now?", "asker": "yardmaster",
                 "since": "2026-10-10T10:00:00Z"},
            ], "decided": []}})
            .to_string(),
        );
        yard.answer("Bead", &bead_three());
        cx.update(|cx| {
            input::bind_keys(cx);
            bind_keys(cx);
        });
        let (view, cx) = cx.add_window_view(|window, cx| {
            let view = Footplate::new(yard.client(), "jo".into(), window, cx);
            window.focus(&view.line.focus_handle(cx));
            view
        });
        // The remembered mode, before the yard answers: the window opens
        // in decisions, and no other head is ever drawn.
        view.update(cx, |v, cx| {
            v.set(
                v.settings
                    .clone()
                    .with_mode(settings::HERE, Mode::Decisions),
                cx,
            );
        });
        wait(cx, "the decision", |cx| {
            view.read_with(cx, |v, _| {
                v.model.as_ref().is_some_and(|m| m.decisions_count() == 1)
            })
        });
        assert_eq!(rail_mode(&view, cx), Mode::Decisions);
        assert!(drawn(cx, "section Decisions"));
        assert!(drawn(cx, "section Decisions count"));
        assert!(!drawn(cx, "section Crew"));
        assert!(!drawn(cx, "section Timetable"));
        for title in ["Decisions", "Crew", "Timetable"] {
            match title {
                "Decisions" => to_decisions(&view, cx),
                "Crew" => to_chat(&view, cx),
                _ => to_timetable(&view, cx),
            }
            cx.run_until_parked();
            let head_name = format!("section {title}");
            let count_name = format!("section {title} count");
            assert!(drawn(cx, &head_name), "no {title} head in its mode");
            assert!(drawn(cx, &count_name), "no {title} count in its mode");
            let head = bounds_of(cx, &head_name);
            let count = bounds_of(cx, &count_name);
            let rows = bounds_of(cx, "rows");
            assert!(
                head.right() <= count.left() && count.right() <= rows.right() + px(1.),
                "the count is not at its head's right end: {head:?} {count:?} {rows:?}"
            );
            assert!(
                head.top() <= count.bottom() && count.top() <= head.bottom(),
                "the count stands off its head's row: {head:?} {count:?}"
            );
        }
    }

    /// With nothing to decide the Decisions head still stands, in
    /// decisions alone; in chat the Crew head stands over the
    /// conversations with the yard row below them, and the arrivals row
    /// in timetable.
    #[gpui::test]
    fn without_decisions_the_crew_head_stands_alone(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        wait(cx, "the yard", |cx| {
            view.read_with(cx, |v, _| v.model.is_some())
        });
        assert!(!drawn(cx, "section Decisions"));
        assert!(!drawn(cx, "section Decisions count"));
        assert!(drawn(cx, "section Crew"));
        assert!(drawn(cx, "section Crew count"));
        assert!(drawn(cx, "row name yardmaster"));
        assert!(drawn(cx, "row yard"));
        assert!(!drawn(cx, "row arrivals"));
        // The Decisions head stands in decisions, over no rows. (What
        // was drawn stays drawn to the tests, so the Crew head gone from
        // the list is not said here; the sections test opens in
        // decisions, where no Crew head is ever drawn.)
        to_decisions(&view, cx);
        cx.run_until_parked();
        assert!(drawn(cx, "section Decisions"));
        assert!(drawn(cx, "section Decisions count"));
        // Nothing in transit: the row says so, in timetable.
        to_timetable(&view, cx);
        cx.run_until_parked();
        assert!(drawn(cx, "row arrivals"));
        view.read_with(cx, |v, _| {
            assert_eq!(
                v.model.as_ref().unwrap().arrivals_row().line,
                "none in transit"
            );
        });
    }

    /// The timetable's list holds the arrivals row, counting what is in
    /// transit. A click on it opens the board: the served rows grouped by
    /// platform, the platforms in the served travel order, each with its
    /// rows in the served order and remarked as served.
    #[gpui::test]
    fn the_arrivals_row_opens_the_board_grouped_by_platform(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("Arrivals", &arrivals_board());
        yard.answer("Flows", &flows_board());
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        // The crew stands in chat, and the arrivals row in timetable.
        assert!(drawn(cx, "row name yardmaster"));
        assert!(!drawn(cx, "row arrivals"));
        assert!(!drawn(cx, "arrival yd-zulu"));
        to_timetable(&view, cx);
        cx.run_until_parked();
        assert!(drawn(cx, "row arrivals"));
        view.read_with(cx, |v, _| {
            assert_eq!(
                v.model.as_ref().unwrap().arrivals_row().line,
                "3 in transit"
            );
        });
        // The board on a click: the groups in the served order,
        // review's one row before draft's two, though draft appears
        // first in the served rows.
        click_on(cx, "row arrivals");
        wait(cx, "the arrivals", |cx| drawn(cx, "arrival yd-zulu"));
        view.read_with(cx, |v, _| {
            assert_eq!(
                v.model.as_ref().unwrap().selected(),
                Some(&Selected::Arrivals)
            );
        });
        assert!(drawn(cx, "arrivals head"));
        assert!(drawn(cx, "arrival group draft"));
        assert!(drawn(cx, "arrival group draft count"));
        assert!(drawn(cx, "arrival group review"));
        assert!(drawn(cx, "arrival group review count"));
        for bead in ["yd-zulu", "yd-alpha", "footplate-p512"] {
            assert!(drawn(cx, &format!("arrival {bead}")), "{bead}");
            assert!(drawn(cx, &format!("arrival title {bead}")), "{bead}");
            assert!(drawn(cx, &format!("arrival time {bead}")), "{bead}");
            assert!(drawn(cx, &format!("arrival sub {bead}")), "{bead}");
        }
        let review = bounds_of(cx, "arrival group review").top();
        let alpha = bounds_of(cx, "arrival yd-alpha").top();
        let draft = bounds_of(cx, "arrival group draft").top();
        let zulu = bounds_of(cx, "arrival yd-zulu").top();
        let p512 = bounds_of(cx, "arrival footplate-p512").top();
        assert!(
            review < alpha && alpha < draft && draft < zulu && zulu < p512,
            "the groups stand out of the served order: {review:?} {alpha:?} {draft:?} {zulu:?} {p512:?}"
        );
        // The rows as served: late, none, and held, with their tones,
        // and no sorting or remarking of the window's own.
        assert!(drawn(cx, "arrival remark yd-zulu"));
        assert!(!drawn(cx, "arrival remark yd-alpha"));
        assert!(drawn(cx, "arrival remark footplate-p512"));
        view.read_with(cx, |v, _| {
            let model = v.model.as_ref().unwrap();
            assert_eq!(
                model
                    .arrival_rows()
                    .iter()
                    .map(|row| (
                        row.bead.as_str(),
                        row.platform.as_str(),
                        row.remark.as_str(),
                        row.tone.as_str()
                    ))
                    .collect::<Vec<_>>(),
                [
                    ("yd-zulu", "draft", "late", "amber"),
                    ("yd-alpha", "review", "", "none"),
                    ("footplate-p512", "draft", "held", "red"),
                ]
            );
            let groups = model.arrival_groups();
            assert_eq!(groups.len(), 2);
            assert_eq!(groups[0].platform, "review");
            assert_eq!(groups[0].rows.len(), 1);
            assert_eq!(groups[1].platform, "draft");
            assert_eq!(groups[1].rows.len(), 2);
        });
        // Three travel and three show: no capped line stands.
        assert!(!drawn(cx, "arrivals capped"));
    }

    /// Against a yard that serves no platforms list the board still
    /// draws, grouped as it always was: the platforms in the order
    /// they first appear in the served order.
    #[gpui::test]
    fn without_a_platforms_list_the_board_groups_in_first_appearance_order(
        cx: &mut TestAppContext,
    ) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("Arrivals", &arrivals_board_no_list());
        yard.answer("Flows", &flows_board());
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        to_timetable(&view, cx);
        click_on(cx, "row arrivals");
        wait(cx, "the arrivals", |cx| drawn(cx, "arrival yd-zulu"));
        assert!(drawn(cx, "arrival group draft"));
        assert!(drawn(cx, "arrival group review"));
        // Draft's two rows before review's one: first appearance, as
        // the board drew before the yard served the list.
        let draft = bounds_of(cx, "arrival group draft").top();
        let zulu = bounds_of(cx, "arrival yd-zulu").top();
        let p512 = bounds_of(cx, "arrival footplate-p512").top();
        let review = bounds_of(cx, "arrival group review").top();
        let alpha = bounds_of(cx, "arrival yd-alpha").top();
        assert!(
            draft < zulu && zulu < p512 && p512 < review && review < alpha,
            "the groups stand out of arrival order: {draft:?} {zulu:?} {p512:?} {review:?} {alpha:?}"
        );
        view.read_with(cx, |v, _| {
            let groups = v.model.as_ref().unwrap().arrival_groups();
            assert_eq!(groups.len(), 2);
            assert_eq!(groups[0].platform, "draft");
            assert_eq!(groups[1].platform, "review");
        });
    }

    /// A board row's click opens the bead's details: the title, id,
    /// platform and line, the expected arrival and remark of its row,
    /// the labels, the body, then the notes newest last with their
    /// author and time. Its asks are one line that links nothing, and a
    /// quiet arrivals link leads back to the board.
    #[gpui::test]
    fn a_board_row_s_click_opens_the_bead_s_details(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("Arrivals", &arrivals_board());
        yard.answer("Flows", &flows_board());
        yard.answer("Bead", &bead_zulu());
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        to_timetable(&view, cx);
        click_on(cx, "row arrivals");
        wait(cx, "the arrivals", |cx| drawn(cx, "arrival yd-zulu"));
        // The bead from the Bead call, through a row's click.
        click_on(cx, "arrival yd-zulu");
        wait(cx, "the bead", |cx| drawn(cx, "bead back"));
        view.read_with(cx, |v, _| {
            let model = v.model.as_ref().unwrap();
            assert_eq!(model.selected(), Some(&Selected::Bead("yd-zulu".into())));
            assert!(model.arrivals_row().selected);
            let detail = model.arrival_detail("yd-zulu").unwrap();
            assert_eq!(detail.title, "Zulu's late turn");
            assert_eq!(detail.stage, "draft");
            assert_eq!(detail.line, "yardr");
            assert_eq!(detail.expected, "5h–8h");
            assert_eq!(detail.remark, "late");
            assert_eq!(detail.labels, ["size:medium", "eyes"]);
            assert_eq!(detail.body, "The turn the yard waits on.");
            assert_eq!(
                detail
                    .notes
                    .iter()
                    .map(|n| (n.author.as_str(), n.at.as_str()))
                    .collect::<Vec<_>>(),
                [
                    ("assembly", "2026-10-10T10:30:00Z"),
                    ("yardmaster", "2026-10-10T11:30:00Z"),
                ]
            );
            assert_eq!(detail.open_asks, 2);
        });
        assert!(drawn(cx, "bead title yd-zulu"));
        assert!(drawn(cx, "bead sub yd-zulu"));
        assert!(drawn(cx, "bead remark yd-zulu"));
        assert!(drawn(cx, "bead labels yd-zulu"));
        assert!(drawn(cx, "bead asks yd-zulu"));
        // The asks line links nothing: a click leaves the bead open.
        click_on(cx, "bead asks yd-zulu");
        cx.run_until_parked();
        view.read_with(cx, |v, _| {
            assert_eq!(
                v.model.as_ref().unwrap().selected(),
                Some(&Selected::Bead("yd-zulu".into()))
            );
        });
        // And back to the board on the arrivals link.
        click_on(cx, "bead back");
        wait(cx, "the board again", |cx| {
            view.read_with(cx, |v, _| {
                v.model.as_ref().unwrap().selected() == Some(&Selected::Arrivals)
            })
        });
    }

