    /// Each yard reopens in its remembered mode, and each mode on the row
    /// it was left on: stepping modes keeps each mode's row, switching
    /// yards keeps each yard's mode, and the settings keep both.
    #[gpui::test]
    fn each_yard_reopens_in_its_mode_and_each_mode_on_its_row(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let near = Yard::start();
        a_yard_of_jo(&near);
        near.answer(
            "UserAsks",
            &json!({"result": {"open": [
                {"bead": "bead-a", "bead_title": "Move the links", "topic": "topic:linear-out",
                 "ask": 3, "question": "Move them now?", "asker": "yardmaster",
                 "since": "2026-10-10T10:00:00Z"},
            ], "decided": []}})
            .to_string(),
        );
        near.answer("Bead", &bead_three());
        let second = Yard::start();
        a_second_yard_of_jo(&second);
        let file = dir.path().join("footplate/settings.json");
        Settings::default()
            .with_yard(
                None,
                settings::Yard::near("second home", second.socket().to_str().unwrap()),
                None,
            )
            .unwrap()
            .write(&file)
            .unwrap();
        let env = Env {
            socket: near.socket().to_path_buf(),
            ..Env::default()
        };
        let (view, cx) = opened_at(env, &file, cx);
        wait(cx, "this machine's yard", |cx| {
            texts(&view, cx) == ["Shall I land it?"]
        });
        // Into decisions, on the card; back to chat, on the
        // conversation; into decisions again, on the card still.
        to_decisions(&view, cx);
        wait(cx, "the card", |cx| {
            open_row(&view, cx) == Some(Selected::Decision("bead-a".into()))
        });
        to_chat(&view, cx);
        cx.run_until_parked();
        assert_eq!(
            open_row(&view, cx),
            Some(Selected::Conversation("yardmaster".into()))
        );
        to_decisions(&view, cx);
        cx.run_until_parked();
        assert_eq!(
            open_row(&view, cx),
            Some(Selected::Decision("bead-a".into()))
        );
        // The second yard opens in chat, as never stepped; stepped to
        // the timetable, it stays there.
        cx.simulate_keystrokes("secondary-2");
        wait(cx, "the second home's yard", |cx| {
            texts(&view, cx) == ["From the second home."]
        });
        assert_eq!(rail_mode(&view, cx), Mode::Chat);
        to_timetable(&view, cx);
        cx.run_until_parked();
        assert_eq!(open_row(&view, cx), Some(Selected::Arrivals));
        // Back to the first: decisions, on the card. And back to the
        // second: the timetable, on the arrivals row.
        cx.simulate_keystrokes("secondary-1");
        wait(cx, "this machine's yard in decisions", |cx| {
            rail_mode(&view, cx) == Mode::Decisions
                && open_row(&view, cx) == Some(Selected::Decision("bead-a".into()))
        });
        cx.simulate_keystrokes("secondary-2");
        wait(cx, "the second home's yard in the timetable", |cx| {
            rail_mode(&view, cx) == Mode::Timetable
                && open_row(&view, cx) == Some(Selected::Arrivals)
        });
        // The settings keep each yard's mode.
        let kept = Settings::read(&file);
        assert_eq!(kept.mode_of("this machine"), Mode::Decisions);
        assert_eq!(kept.mode_of("second home"), Mode::Timetable);
    }

    /// A yard at its listener, told from `a_yard_of_jo` by its mail.
    /// A system for a test: what it was asked and shown is read here, and
    /// what it answers and what a person activates is said here.
    #[derive(Clone)]
    struct Told {
        answer: Rc<RefCell<Permission>>,
        asked: Rc<Cell<usize>>,
        shown: Rc<RefCell<Vec<notify::Telling>>>,
        activated: (
            async_channel::Sender<notify::Activated>,
            async_channel::Receiver<notify::Activated>,
        ),
    }

    impl Told {
        fn new() -> Told {
            Told {
                answer: Rc::new(RefCell::new(Permission::Allowed)),
                asked: Rc::new(Cell::new(0)),
                shown: Rc::default(),
                activated: async_channel::unbounded(),
            }
        }

        /// What was shown since the last look, once a burst's time is over.
        fn shown(&self, cx: &mut VisualTestContext) -> Vec<(String, String, Selected)> {
            self.tellings(cx)
                .into_iter()
                .map(|telling| (telling.title, telling.body, telling.target))
                .collect()
        }

        /// The same, each with the yard it tells of.
        fn tellings(&self, cx: &mut VisualTestContext) -> Vec<notify::Telling> {
            cx.run_until_parked();
            cx.executor().advance_clock(notify::BURST);
            cx.run_until_parked();
            std::mem::take(&mut *self.shown.borrow_mut())
        }
    }

    impl notify::System for Told {
        fn ask(&self) -> async_channel::Receiver<Permission> {
            self.asked.set(self.asked.get() + 1);
            let (tell, told) = async_channel::bounded(1);
            tell.try_send(self.answer.borrow().clone()).unwrap();
            told
        }

        fn show(&self, telling: &notify::Telling) {
            self.shown.borrow_mut().push(telling.clone());
        }

        fn activated(&self) -> async_channel::Receiver<notify::Activated> {
            self.activated.1.clone()
        }
    }

    fn mail_event(seq: u64, from: &str, text: &str) -> String {
        json!({"seq": seq, "kind": "mail", "actor": from, "at": "2026-10-08T09:31:00Z",
            "data": {"to": "jo", "to_user": true, "text": text}})
        .to_string()
    }

    fn unread_of(view: &Entity<Footplate>, cx: &mut VisualTestContext, from: &str) -> usize {
        view.read_with(cx, |v, _| v.model.as_ref().unwrap().unread(from))
    }

    #[gpui::test]
    fn the_system_tells_of_what_arrives_where_the_window_does_not_show_it(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        cx.update(|cx| {
            input::bind_keys(cx);
            bind_keys(cx);
        });
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        let told = Told::new();
        let (view, cx) = cx.add_window_view(|window, cx| {
            let view = Footplate::new(yard.client(), "jo".into(), window, cx)
                .kept_in(Some(file.clone()), cx)
                .notified_by(Box::new(told.clone()), cx);
            window.focus(&view.line.focus_handle(cx));
            view
        });
        wait(cx, "the yardmaster's conversation", |cx| {
            texts(&view, cx) == ["Shall I land it?"]
        });
        // The window is behind another: everything that arrives is news.
        cx.deactivate_window();
        assert!(!view.read_with(cx, |v, _| v.front));

        // Nobody chose: the system is asked nothing and shows nothing,
        // not for what was unread at the start and not for what arrives.
        yard.emit(&mail_event(21, "assembly", "Built."));
        wait(cx, "the unread mail", |cx| {
            unread_of(&view, cx, "assembly") == 1
        });
        assert_eq!(told.shown(cx), []);
        assert_eq!(told.asked.get(), 0);

        // Switched on in the settings: the system is asked, once, and what
        // it refuses is said there in its words.
        *told.answer.borrow_mut() = Permission::Refused("The system says no.".into());
        cx.simulate_keystrokes("secondary-,");
        click_on(cx, "settings section notifications");
        assert!(!drawn(cx, "notify mail"));
        click_on(cx, "notify on");
        assert!(settings_of(&view, cx).notifications.on);
        assert!(Settings::read(&file).notifications.on);
        assert_eq!(told.asked.get(), 1);
        assert!(drawn(cx, "notify said"));
        assert_eq!(
            view.read_with(cx, |v, _| v.permission.clone()),
            Some(Permission::Refused("The system says no.".into()))
        );
        // Off and on again, it is asked again, and what it says now
        // stands for what it said before.
        click_on(cx, "notify off");
        assert!(!Settings::read(&file).notifications.on);
        *told.answer.borrow_mut() = Permission::Allowed;
        click_on(cx, "notify on");
        assert_eq!(told.asked.get(), 2);
        cx.run_until_parked();
        assert_eq!(
            view.read_with(cx, |v, _| v.permission.clone()),
            Some(Permission::Allowed)
        );
        // What tells is chosen kind by kind, and kept.
        click_on(cx, "notify the yard's notices");
        click_on(cx, "notify decisions");
        let chosen = Notify {
            on: true,
            mail: true,
            decisions: false,
            notices: true,
        };
        assert_eq!(settings_of(&view, cx).notifications, chosen);
        assert_eq!(Settings::read(&file).notifications, chosen);
        click_on(cx, "notify the yard's notices");
        click_on(cx, "notify decisions");
        assert_eq!(
            Settings::read(&file).notifications,
            Notify {
                on: true,
                ..Notify::default()
            }
        );
        // Choosing told of nothing that was there before.
        click_on(cx, "settings back");
        assert_eq!(told.shown(cx), []);

        // Behind another window, mail in the open conversation is told of:
        // who it is from, and its first line.
        yard.emit(&mail_event(22, "yardmaster", "Landed.\nThe tests held."));
        wait(cx, "the mail", |cx| texts(&view, cx).len() == 2);
        assert_eq!(
            told.shown(cx),
            [(
                "yardmaster".to_string(),
                "Landed.".to_string(),
                Selected::Conversation("yardmaster".into())
            )]
        );

        // Turning notifications off during a pending burst cancels it.
        yard.emit(&mail_event(23, "assembly", "This should not arrive."));
        wait(cx, "the pending mail", |cx| {
            unread_of(&view, cx, "assembly") == 2
        });
        cx.simulate_keystrokes("secondary-,");
        click_on(cx, "settings section notifications");
        click_on(cx, "notify off");
        assert_eq!(told.shown(cx), []);
        click_on(cx, "notify on");
        click_on(cx, "settings back");

        // In front on that conversation it is read where it stands.
        cx.update(|window, _| window.activate_window());
        cx.run_until_parked();
        assert!(view.read_with(cx, |v, _| v.front));
        yard.emit(&mail_event(24, "yardmaster", "And pushed."));
        wait(cx, "the mail", |cx| texts(&view, cx).len() == 3);
        assert_eq!(told.shown(cx), []);
        // With the settings where the conversation would be, it is not.
        cx.simulate_keystrokes("secondary-,");
        yard.emit(&mail_event(25, "yardmaster", "Shall I go on?"));
        wait(cx, "the mail", |cx| texts(&view, cx).len() == 4);
        assert_eq!(told.shown(cx).len(), 1);
        cx.simulate_keystrokes("secondary-,");

        // In front on another conversation: a burst is one notification.
        for (seq, text) in [(26, "One."), (27, "Two."), (28, "Three.")] {
            yard.emit(&mail_event(seq, "assembly", text));
        }
        wait(cx, "the burst", |cx| unread_of(&view, cx, "assembly") == 5);
        assert_eq!(
            told.shown(cx),
            [(
                "3 from assembly".to_string(),
                "Three.".to_string(),
                Selected::Conversation("assembly".into())
            )]
        );
        // And the next after it is one of its own.
        yard.emit(&mail_event(29, "assembly", "Four."));
        wait(cx, "the mail", |cx| unread_of(&view, cx, "assembly") == 6);
        assert_eq!(told.shown(cx).len(), 1);

        // What the person wrote, here or elsewhere, tells of nothing.
        cx.deactivate_window();
        yard.emit(r#"{"seq": 30, "kind": "mail", "actor": "jo", "data": {"to": "yardmaster", "text": "Go on."}, "at": "2026-10-08T09:31:00Z"}"#);
        wait(cx, "the user's own mail", |cx| texts(&view, cx).len() == 5);
        assert_eq!(told.shown(cx), []);

        // A new decision is told of, by who asks and the question.
        yard.answer(
            "UserAsks",
            r#"{"result": {"open": [{"bead": "bead-a", "bead_title": "Move the links", "topic": "",
                "ask": 3, "question": "Move them now?", "asker": "yardmaster",
                "since": "2026-10-10T10:00:00Z"}], "decided": []}}"#,
        );
        yard.emit(r#"{"seq": 31, "kind": "noted", "actor": "yardmaster", "bead": "bead-a", "data": {"note": 3}, "at": "2026-10-08T09:31:00Z"}"#);
        wait(cx, "the decision", |cx| {
            to_decisions(&view, cx);
            view.read_with(cx, |v, _| v.model.as_ref().unwrap().decisions_count() == 1)
        });
        assert_eq!(
            told.shown(cx),
            [(
                "yardmaster asks".to_string(),
                "Move them now?".to_string(),
                Selected::Decision("bead-a".into())
            )]
        );

        // Activating a notification brings the window forward on its row,
        // out of the settings too.
        cx.simulate_keystrokes("secondary-,");
        assert!(settings_open(&view, cx));
        let open = view.read_with(cx, |v, _| v.yard.clone());
        told.activated
            .0
            .try_send((open.clone(), Selected::Conversation("assembly".into())))
            .unwrap();
        cx.run_until_parked();
        assert!(view.read_with(cx, |v, _| v.front));
        assert!(!settings_open(&view, cx));
        assert_eq!(
            view.read_with(cx, |v, _| v.model.as_ref().unwrap().selected().cloned()),
            Some(Selected::Conversation("assembly".into()))
        );
        // A row that is gone since leaves open what was.
        told.activated
            .0
            .try_send((open, Selected::Decision("bead-gone".into())))
            .unwrap();
        cx.run_until_parked();
        assert_eq!(
            view.read_with(cx, |v, _| v.model.as_ref().unwrap().selected().cloned()),
            Some(Selected::Conversation("assembly".into()))
        );

        // Kept on, the next start asks the system at once.
        let (again, cx) = {
            let (client, file, told) = (yard.client(), file.clone(), told.clone());
            let asked = told.asked.get();
            let (again, cx) = cx.add_window_view(|window, cx| {
                Footplate::new(client, "jo".into(), window, cx)
                    .notified_by(Box::new(told.clone()), cx)
                    .kept_in(Some(file), cx)
            });
            assert_eq!(told.asked.get(), asked + 1);
            (again, cx)
        };
        cx.run_until_parked();
        assert_eq!(
            again.read_with(cx, |v, _| v.permission.clone()),
            Some(Permission::Allowed)
        );
    }

    /// A window on this machine's yard and a second home's, both followed,
    /// with `told` for its notifications, which are on: the mail and the
    /// decisions tell, and the notices where `notices` says so.
    fn opened_on_two_yards<'a>(
        dir: &std::path::Path,
        (near, second): (&Yard, &Yard),
        told: &Told,
        notices: bool,
        cx: &'a mut TestAppContext,
    ) -> (Entity<Footplate>, &'a mut VisualTestContext) {
        let file = dir.join("footplate/settings.json");
        let mut set = Settings::default()
            .with_yard(
                None,
                settings::Yard::near("second home", second.socket().to_str().unwrap()),
                None,
            )
            .unwrap();
        set.notifications.on = true;
        set.notifications.notices = notices;
        set.write(&file).unwrap();
        cx.update(|cx| {
            input::bind_keys(cx);
            bind_keys(cx);
        });
        let env = Env {
            socket: near.socket().to_path_buf(),
            ..Env::default()
        };
        let told = told.clone();
        let (view, cx) = cx.add_window_view(|window, cx| {
            let view = Footplate::opened(env, "jo".into(), Some(file.clone()), window, cx)
                .notified_by(Box::new(told), cx);
            window.focus(&view.line.focus_handle(cx));
            view
        });
        wait(cx, "this machine's yard", |cx| {
            texts(&view, cx) == ["Shall I land it?"]
        });
        wait(cx, "what waits in the second home's yard", |cx| {
            state_of(&view, cx, "second home") == "2 mail"
        });
        // The stream is asked for after the state above arrived, so it may
        // not have been asked for yet.
        wait(cx, "the second home's stream", |_| {
            second.streams_asked().len() == 1
        });
        (view, cx)
    }

    /// Every yard of the settings is followed at once. What arrives in one
    /// that is not open is counted in the switcher as it arrives, with no
    /// switch, and nothing of it is marked read. The system tells of it by
    /// the settings' kinds, in a notification that names its yard, and a
    /// burst of two yards says each yard's part. Activated, a notification
    /// opens its yard on its row, as the yard stands: it is not read from
    /// nothing.
    #[gpui::test]
    fn a_yard_that_is_not_open_counts_what_arrives_and_its_notification_opens_it(
        cx: &mut TestAppContext,
    ) {
        let dir = tempfile::tempdir().unwrap();
        let near = Yard::start();
        a_yard_of_jo(&near);
        let second = Yard::start();
        a_second_yard_of_jo(&second);
        let told = Told::new();
        let (view, cx) = opened_on_two_yards(dir.path(), (&near, &second), &told, true, cx);
        let open_row = |cx: &mut VisualTestContext| {
            view.read_with(cx, |v, _| v.model.as_ref().unwrap().selected().cloned())
        };
        let tellings = |cx: &mut VisualTestContext| -> Vec<(String, String, String, Selected)> {
            told.tellings(cx)
                .into_iter()
                .map(|t| (t.title, t.body, t.yard, t.target))
                .collect()
        };
        let telling = |title: &str, body: &str, yard: &str, target: Selected| {
            (
                title.to_string(),
                body.to_string(),
                yard.to_string(),
                target,
            )
        };
        // What was unread when the window started tells of nothing.
        assert_eq!(tellings(cx), []);
        let (loads, streams) = (second.asked("Head").len(), second.streams_asked().len());
        assert_eq!(streams, 1);
        // The dock's icon says what waits over both yards: nothing in the
        // open one, whose mail is read, and the two of the other.
        assert_eq!(badge_of(&view, cx), 2);

        // Mail arrives in the yard that is not open, with the window in
        // front on the other: it is counted where the switcher says what
        // waits there, and told of as that yard's. Nothing of it is shown,
        // so the yard is not told it was read.
        cx.update(|window, _| window.activate_window());
        cx.run_until_parked();
        assert!(view.read_with(cx, |v, _| v.front));
        second.emit(&mail_event(21, "assembly", "Built."));
        wait(cx, "the mail in the second home's yard", |cx| {
            state_of(&view, cx, "second home") == "3 mail"
        });
        assert_eq!(open_yard(&view, cx), "this machine");
        assert_eq!(texts(&view, cx), ["Shall I land it?"]);
        assert_eq!(
            tellings(cx),
            [telling(
                "second home · assembly",
                "Built.",
                "second home",
                Selected::Conversation("assembly".into())
            )]
        );
        assert_eq!(second.asked("AckUserInbox").len(), 0);
        // The icon counts it, of a yard that is not shown.
        assert_eq!(badge_of(&view, cx), 3);

        // A card: one notification, naming the yard it waits in.
        second.answer("UserAsks", &asks_one());
        second.emit(r#"{"seq": 31, "kind": "noted", "actor": "yardmaster", "bead": "bead-a", "data": {"note": 3}, "at": "2026-10-08T09:31:00Z"}"#);
        wait(cx, "the card in the second home's yard", |cx| {
            state_of(&view, cx, "second home") == "3 mail, 1 decision"
        });
        assert_eq!(
            tellings(cx),
            [telling(
                "second home · yardmaster asks",
                "Move them now?",
                "second home",
                Selected::Decision("bead-a".into())
            )]
        );

        assert_eq!(badge_of(&view, cx), 4);

        // A notice of the yard, which the settings here have tell too.
        second.answer("UserNotifications", &notices_many(1));
        second.emit(r#"{"seq": 32, "kind": "created", "actor": "yard", "bead": "yd-shed", "data": {"notified": {"jo": "all"}}, "at": "2026-10-08T09:32:00Z"}"#);
        wait(cx, "the notice in the second home's yard", |cx| {
            state_of(&view, cx, "second home") == "3 mail, 1 decision, 1 notice"
        });
        assert_eq!(
            tellings(cx),
            [telling(
                "second home · yard",
                "notice 0 of the evening's work",
                "second home",
                Selected::Yard
            )]
        );

        // A notice asks nothing of the person: the icon's number stays.
        assert_eq!(badge_of(&view, cx), 4);

        // A burst of both yards is one notification, each yard's part by
        // itself: a sender of one name in both is not one sender. It leads
        // to the first, in the yard that arrived in.
        near.emit(&mail_event(21, "assembly", "Built here."));
        wait(cx, "the mail in this machine's yard", |cx| {
            unread_of(&view, cx, "assembly") == 1
        });
        second.emit(&mail_event(33, "assembly", "Tested."));
        second.emit(&mail_event(34, "yardmaster", "Landed."));
        wait(cx, "more mail in the second home's yard", |cx| {
            state_of(&view, cx, "second home") == "5 mail, 1 decision, 1 notice"
        });
        assert_eq!(
            tellings(cx),
            [telling(
                "3 new in 2 yards",
                "this machine: 1 from assembly; second home: 1 from assembly, 1 from yardmaster",
                "this machine",
                Selected::Conversation("assembly".into())
            )]
        );

        // The card's notification is activated: the window shows the yard
        // it waits in, on the card's row. The yard is shown as it was
        // held: it is not read again, and its stream is the one it had.
        told.activated
            .0
            .try_send(("second home".into(), Selected::Decision("bead-a".into())))
            .unwrap();
        cx.run_until_parked();
        assert!(view.read_with(cx, |v, _| v.front));
        assert_eq!(open_yard(&view, cx), "second home");
        assert_eq!(open_row(cx), Some(Selected::Decision("bead-a".into())));
        assert_eq!(state_of(&view, cx, "second home"), "open");
        assert_eq!(second.asked("Head").len(), loads);
        assert_eq!(second.streams_asked().len(), streams);
        // The yard that was left is followed still, and says what waits.
        assert_eq!(state_of(&view, cx, "this machine"), "1 mail");
        // The icon's number is of every yard, whichever is open: the one
        // of the yard that was left, and five mail and the card of this.
        assert_eq!(badge_of(&view, cx), 7);
        near.emit(&mail_event(22, "assembly", "And pushed."));
        wait(cx, "mail in the yard that was left", |cx| {
            state_of(&view, cx, "this machine") == "2 mail"
        });
        assert_eq!(
            tellings(cx),
            [telling(
                "this machine · assembly",
                "And pushed.",
                "this machine",
                Selected::Conversation("assembly".into())
            )]
        );

        // A notification of a yard that is listed no longer opens nothing:
        // a row of its name in the open yard is another conversation, and
        // what is typed in it would be sent to the wrong yard.
        let before = open_row(cx);
        told.activated
            .0
            .try_send(("gone".into(), Selected::Conversation("assembly".into())))
            .unwrap();
        cx.run_until_parked();
        assert_eq!(open_yard(&view, cx), "second home");
        assert_eq!(open_row(cx), before);
        // One of the open yard leads to its row, as before.
        told.activated
            .0
            .try_send((
                "second home".into(),
                Selected::Conversation("assembly".into()),
            ))
            .unwrap();
        cx.run_until_parked();
        assert_eq!(open_yard(&view, cx), "second home");
        assert_eq!(
            open_row(cx),
            Some(Selected::Conversation("assembly".into()))
        );
    }

    /// What the menu bar's item was last told to say: its title, and what
    /// each yard's row says. None while there is no item.
    fn tray_of(
        view: &Entity<Footplate>,
        cx: &mut VisualTestContext,
    ) -> Option<(String, Vec<String>)> {
        view.read_with(cx, |v, _| {
            let said = v.tray.told()?;
            let rows = said.rows.iter().map(|row| row.says.clone()).collect();
            Some((said.title.clone(), rows))
        })
    }

    /// What the item was last told to say in words, as a tray's tooltip
    /// has it.
    fn tip_of(view: &Entity<Footplate>, cx: &mut VisualTestContext) -> Option<String> {
        view.read_with(cx, |v, _| Some(v.tray.told()?.tip.clone()))
    }

    /// The menu bar's item says the number the dock's icon says, and has a
    /// row for each yard with what waits in it, the open one's too, as it
    /// changes. A yard's row shows the window on that yard, on the row it
    /// was left on, and "Show window" on whatever is open. Switched off in
    /// the settings, there is no item.
    #[gpui::test]
    fn the_menu_bar_item_says_what_waits_in_each_yard_and_a_yard_s_row_opens_it(
        cx: &mut TestAppContext,
    ) {
        use crate::tray::Chosen;

        let dir = tempfile::tempdir().unwrap();
        let near = Yard::start();
        a_yard_of_jo(&near);
        let second = Yard::start();
        a_second_yard_of_jo(&second);
        let told = Told::new();
        let (view, cx) = opened_on_two_yards(dir.path(), (&near, &second), &told, false, cx);
        let open_row = |cx: &mut VisualTestContext| {
            view.read_with(cx, |v, _| v.model.as_ref().unwrap().selected().cloned())
        };
        let choose = |chosen: Chosen, cx: &mut VisualTestContext| {
            view.read_with(cx, |v, _| v.tray.choose(chosen));
            cx.run_until_parked();
        };
        let said = |title: &str, rows: [&str; 2]| {
            Some((title.to_string(), rows.map(str::to_string).to_vec()))
        };
        assert_eq!(
            tray_of(&view, cx),
            said(
                "2",
                ["this machine · nothing waiting", "second home · 2 mail"]
            )
        );
        assert_eq!(tip_of(&view, cx).as_deref(), Some("2 wait: 2 mail"));

        // What arrives is said where the dock's icon is told: in the yard
        // that is not open, and in the open one.
        second.emit(&mail_event(21, "assembly", "Built."));
        wait(cx, "the mail in the second home's yard", |cx| {
            badge_of(&view, cx) == 3
        });
        near.emit(&mail_event(21, "assembly", "Built here."));
        wait(cx, "the mail in this machine's yard", |cx| {
            badge_of(&view, cx) == 4
        });
        assert_eq!(
            tray_of(&view, cx),
            said("4", ["this machine · 1 mail", "second home · 3 mail"])
        );
        // In words it is of every yard at once.
        assert_eq!(tip_of(&view, cx).as_deref(), Some("4 wait: 4 mail"));

        // The row of the yard that is not open shows the window on it, on
        // the yard's own row: it was not left on one. The yard is the one
        // to open at the next start, as from the switcher.
        let here = open_row(cx);
        choose(Chosen::Yard("second home".into()), cx);
        assert_eq!(open_yard(&view, cx), "second home");
        let own = open_row(cx);
        assert!(own.is_some());
        assert_eq!(settings_of(&view, cx).opened().name, "second home");
        // It is left on another row, for the yard it came from, whose row
        // shows the row that one was left on.
        let left_on = Selected::Conversation("assembly".into());
        assert_ne!(own, Some(left_on.clone()));
        let row = left_on.clone();
        cx.update(|window, cx| view.update(cx, |v, cx| v.select(row, window, cx)));
        choose(Chosen::Yard("this machine".into()), cx);
        assert_eq!(open_yard(&view, cx), "this machine");
        assert_eq!(open_row(cx), here);
        // And back: on the row it was left on, not a row the menu names.
        choose(Chosen::Yard("second home".into()), cx);
        assert_eq!(open_yard(&view, cx), "second home");
        assert_eq!(open_row(cx), Some(left_on.clone()));

        // "Show window", the open yard's own row, and the row of a yard
        // that is listed no longer leave open what is open.
        choose(Chosen::Show, cx);
        choose(Chosen::Yard("second home".into()), cx);
        choose(Chosen::Yard("gone".into()), cx);
        assert_eq!(open_yard(&view, cx), "second home");
        assert_eq!(open_row(cx), Some(left_on));

        // A yard that is not reached says so in its row, and what it last
        // had is in the number still.
        choose(Chosen::Yard("this machine".into()), cx);
        let waits = badge_of(&view, cx);
        second.stop();
        wait(cx, "that the second home's yard is not reached", |cx| {
            state_of(&view, cx, "second home") == "not reached: nothing answers"
        });
        let (title, rows) = tray_of(&view, cx).unwrap();
        assert_eq!(title, waits.to_string());
        assert_eq!(rows[1], "second home · not reached: nothing answers");

        // The item follows its setting: off, there is none, and on again
        // it says what it said.
        view.update(cx, |v, cx| v.menu_bar_on(false, cx));
        cx.run_until_parked();
        assert_eq!(tray_of(&view, cx), None);
        view.update(cx, |v, cx| v.menu_bar_on(true, cx));
        cx.run_until_parked();
        assert_eq!(tray_of(&view, cx), Some((title, rows)));
    }

    /// The item's mark is the tray setting's choice, drawn without a
    /// restart: white, black, or as the system draws it. The settings'
    /// buttons choose it, and the file keeps it while it is not auto.
    #[gpui::test]
    fn the_menu_bar_item_s_mark_is_the_tray_setting_s_without_a_restart(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        let (view, cx) = opened_kept(&yard, &file, cx);
        // The control stands low in the settings: the window is tall
        // enough to hold every section, so its buttons take clicks.
        cx.simulate_resize(gpui::size(px(1200.), px(1800.)));
        let marked_of = |cx: &mut VisualTestContext| view.read_with(cx, |v, _| v.tray.marked());
        // Nobody chose: the system's, and the file says nothing of it.
        assert_eq!(marked_of(cx), Look::Auto);
        assert_eq!(settings_of(&view, cx).tray, Look::Auto);
        // The buttons choose it, and the item draws it without a restart.
        click_on(cx, "settings");
        assert!(drawn(cx, "tray auto"));
        click_on(cx, "tray light");
        assert_eq!(settings_of(&view, cx).tray, Look::Light);
        assert_eq!(marked_of(cx), Look::Light);
        assert_eq!(Settings::read(&file).tray, Look::Light);
        click_on(cx, "tray dark");
        assert_eq!(marked_of(cx), Look::Dark);
        click_on(cx, "tray auto");
        assert_eq!(marked_of(cx), Look::Auto);
        assert!(
            !std::fs::read_to_string(&file).unwrap().contains("tray"),
            "auto is left out of the file"
        );
    }

    /// One yard that goes away changes nothing of the others: the stream,
    /// the counts and the sends of the open yard go on while one that is
    /// not open is stopped, and that one is asked again by itself until it
    /// answers. The same the other way: a yard that is not open goes on
    /// counting while the open one is away.
    #[gpui::test]
    fn a_yard_that_goes_away_leaves_the_others_as_they_are_and_is_asked_again(
        cx: &mut TestAppContext,
    ) {
        let dir = tempfile::tempdir().unwrap();
        let near = Yard::start();
        a_yard_of_jo(&near);
        let second = Yard::start();
        a_second_yard_of_jo(&second);
        let told = Told::new();
        let (view, cx) = opened_on_two_yards(dir.path(), (&near, &second), &told, false, cx);

        // The yard that is not open stops.
        let socket = second.socket().to_path_buf();
        second.stop();
        wait(cx, "that the second home's yard is not reached", |cx| {
            state_of(&view, cx, "second home") == "not reached: nothing answers"
        });
        // The open yard shows as it did, on the stream it had: what
        // arrives there arrives, and what is written there is sent.
        assert_eq!(open_yard(&view, cx), "this machine");
        assert_eq!(view.read_with(cx, |v, _| v.down.clone()), None);
        near.emit(&mail_event(21, "yardmaster", "Landed."));
        wait(cx, "the mail in the open yard", |cx| {
            texts(&view, cx) == ["Shall I land it?", "Landed."]
        });
        near.emit(&mail_event(22, "assembly", "Built."));
        wait(cx, "the unread mail in the open yard", |cx| {
            unread_of(&view, cx, "assembly") == 1
        });
        cx.simulate_input("Go on.");
        cx.simulate_keystrokes("enter");
        wait(cx, "the mail to be sent", |_| near.asked("Mail").len() == 1);
        assert_eq!(notice(&view, cx), "");
        assert_eq!(near.streams_asked().len(), 1);
        assert_eq!(
            state_of(&view, cx, "second home"),
            "not reached: nothing answers"
        );
        // The dock's icon counts on: the one that arrived in the open
        // yard, and the two the yard that is not reached last had, which
        // wait there still.
        assert_eq!(badge_of(&view, cx), 3);

        // It is started again: asked again by itself, it says what waits
        // in it, with no switch to it.
        let second = Yard::start_at(&socket);
        a_second_yard_of_jo(&second);
        wait(cx, "the second home's yard to answer by itself", |cx| {
            state_of(&view, cx, "second home") == "2 mail"
        });
        assert_eq!(open_yard(&view, cx), "this machine");
        assert_eq!(near.streams_asked().len(), 1);

        // The open yard stops: the one that is not open goes on, counts
        // what arrives, and has the system tell of it.
        told.tellings(cx);
        near.stop();
        wait(cx, "that the open yard is away", |cx| {
            view.read_with(cx, |v, _| v.down.is_some())
        });
        second.emit(&mail_event(21, "assembly", "Built."));
        wait(cx, "the mail in the yard that is not open", |cx| {
            state_of(&view, cx, "second home") == "3 mail"
        });
        let tellings = told.tellings(cx);
        let [telling] = tellings.as_slice() else {
            panic!("{tellings:?}");
        };
        assert_eq!(telling.title, "second home · assembly");
        assert_eq!(telling.yard, "second home");
        // And it is shown as it stands, from beside the yard that is away.
        cx.simulate_keystrokes("secondary-2");
        wait(cx, "the second home's yard", |cx| {
            texts(&view, cx) == ["From the second home."]
        });
        assert_eq!(
            state_of(&view, cx, "this machine"),
            "not reached: nothing answers"
        );
    }

    fn a_far_yard_of_jo(yard: &Yard) {
        yard.answer("Head", r#"{"result": 40}"#);
        yard.answer(
            "Crew",
            r#"{"result": [{"name": "yardmaster", "enabled": true, "state": "running", "status": "idle"}]}"#,
        );
        yard.answer("Peers", r#"{"result": []}"#);
        yard.answer(
            "Users",
            r#"{"result": [{"name": "jo", "cursor": 5, "notification_cursor": 0}]}"#,
        );
        yard.answer(
            "GetUser",
            r#"{"result": {"name": "jo", "cursor": 30, "notification_cursor": 0}}"#,
        );
        yard.answer(
            "UserInbox",
            r#"{"result": {"mail": [{"seq": 32, "from": "yardmaster", "to": "jo", "text": "From afar.", "read": false}], "unread": 1, "last": 32, "from": ["yardmaster"]}}"#,
        );
        yard.answer(
            "Conversation",
            r#"{"result": [{"seq": 32, "at": "2026-10-08T09:30:00Z", "from": "yardmaster", "to": "jo", "text": "From afar.", "read": false}]}"#,
        );
        yard.answer("AckUserInbox", "{}");
        yard.answer(
            "UserNotifications",
            r#"{"result": {"notifications": [], "unread": 0, "last": 0}}"#,
        );
        yard.answer("UserAsks", r#"{"result": {"open": [], "decided": []}}"#);
        yard.answer("Arrivals", r#"{"result": []}"#);
    }

    /// The window as footplate opens it: on the yard `env` names, else the
    /// one the settings in `file` choose.
    fn opened_at<'a>(
        env: Env,
        file: &std::path::Path,
        cx: &'a mut TestAppContext,
    ) -> (Entity<Footplate>, &'a mut VisualTestContext) {
        let file = file.to_path_buf();
        cx.update(|cx| {
            input::bind_keys(cx);
            bind_keys(cx);
        });
        cx.add_window_view(|window, cx| {
            let view = Footplate::opened(env, "jo".into(), Some(file), window, cx);
            window.focus(&view.line.focus_handle(cx));
            view
        })
    }

    /// Puts a yard's name, its address and a code where they are typed.
    fn type_in(
        view: &Entity<Footplate>,
        cx: &mut VisualTestContext,
        name: &str,
        address: &str,
        code: &str,
    ) {
        view.update(cx, |v, cx| {
            v.yard_name.update(cx, |line, cx| line.set_text(name, cx));
            v.address.update(cx, |line, cx| line.set_text(address, cx));
            v.code.update(cx, |line, cx| line.set_text(code, cx));
        });
    }

    /// Puts a hosted yard's name, its origin and a sign-in's email and
    /// password where they are typed.
    fn type_sign_in(
        view: &Entity<Footplate>,
        cx: &mut VisualTestContext,
        name: &str,
        address: &str,
        email: &str,
        password: &str,
    ) {
        view.update(cx, |v, cx| {
            v.yard_name.update(cx, |line, cx| line.set_text(name, cx));
            v.address.update(cx, |line, cx| line.set_text(address, cx));
            v.email.update(cx, |line, cx| line.set_text(email, cx));
            v.password
                .update(cx, |line, cx| line.set_text(password, cx));
        });
    }

    /// What came of the last change to the yards.
    fn yard_said(view: &Entity<Footplate>, cx: &mut VisualTestContext) -> String {
        view.read_with(cx, |v, _| v.yard_said.clone().unwrap_or_default())
    }

    fn which_yard(view: &Entity<Footplate>, cx: &mut VisualTestContext) -> String {
        view.read_with(cx, |v, _| v.which_yard())
    }

    /// The name of the yard that is open, as the rail's tile names it.
    fn open_yard(view: &Entity<Footplate>, cx: &mut VisualTestContext) -> String {
        view.read_with(cx, |v, _| v.which_yard_short())
    }

    /// What the switcher says of the yard called `name` after its kind.
    fn state_of(view: &Entity<Footplate>, cx: &mut VisualTestContext, name: &str) -> String {
        view.read_with(cx, |v, _| v.yard_state(v.settings.yard(name).unwrap()))
    }

    /// The number the dock's icon was last told.
    fn badge_of(view: &Entity<Footplate>, cx: &mut VisualTestContext) -> usize {
        view.read_with(cx, |v, _| v.waiting)
    }

    fn switching(view: &Entity<Footplate>, cx: &mut VisualTestContext) -> Option<usize> {
        view.read_with(cx, |v, _| v.switching)
    }

    /// The rail's mode in the open yard.
    fn rail_mode(view: &Entity<Footplate>, cx: &mut VisualTestContext) -> Mode {
        view.read_with(cx, |v, _| v.mode())
    }

    /// Steps the rail to decisions, from any mode, as the brackets do.
    /// Idempotent: in decisions already, it changes nothing.
    fn to_decisions(view: &Entity<Footplate>, cx: &mut VisualTestContext) {
        match rail_mode(view, cx) {
            Mode::Chat => cx.simulate_keystrokes("secondary-]"),
            Mode::Timetable => cx.simulate_keystrokes("secondary-["),
            Mode::Decisions => (),
        }
    }

    /// Steps the rail to the timetable, from any mode.
    fn to_timetable(view: &Entity<Footplate>, cx: &mut VisualTestContext) {
        match rail_mode(view, cx) {
            Mode::Chat => cx.simulate_keystrokes("secondary-] secondary-]"),
            Mode::Decisions => cx.simulate_keystrokes("secondary-]"),
            Mode::Timetable => (),
        }
    }

    /// Steps the rail to chat, from any mode.
    fn to_chat(view: &Entity<Footplate>, cx: &mut VisualTestContext) {
        match rail_mode(view, cx) {
            Mode::Decisions => cx.simulate_keystrokes("secondary-["),
            Mode::Timetable => cx.simulate_keystrokes("secondary-[ secondary-["),
            Mode::Chat => (),
        }
    }

    fn mode_of(file: &std::path::Path) -> u32 {
        use std::os::unix::fs::PermissionsExt;
        std::fs::metadata(file).unwrap().permissions().mode() & 0o777
    }

    /// A second home's yard on this machine: jo's too, with other mail, one
    /// of it in a conversation that is not open.
    fn a_second_yard_of_jo(yard: &Yard) {
        a_yard_of_jo(yard);
        yard.answer(
            "UserInbox",
            r#"{"result": {"mail": [{"seq": 12, "from": "yardmaster", "to": "jo", "text": "From the second home.", "read": false},
                {"seq": 13, "from": "assembly", "to": "jo", "text": "Assembled.", "read": false}], "unread": 2, "last": 13, "from": ["yardmaster", "assembly"]}}"#,
        );
        yard.answer(
            "Conversation",
            r#"{"result": [{"seq": 12, "at": "2026-10-08T09:30:00Z", "from": "yardmaster", "to": "jo", "text": "From the second home.", "read": false}]}"#,
        );
    }

    #[test]
    fn what_waits_over_the_yards_is_their_mail_and_decisions_summed() {
        let counts = |mail, decisions, notices| {
            Some(Counts {
                mail,
                decisions,
                notices,
            })
        };
        // No yard, and one where nothing waits.
        assert_eq!(waiting([]), 0);
        assert_eq!(waiting([counts(0, 0, 0)]), 0);
        // One yard: its mail and its decisions, and not its notices.
        assert_eq!(waiting([counts(2, 1, 0)]), 3);
        assert_eq!(waiting([counts(0, 0, 4)]), 0);
        // Several.
        assert_eq!(
            waiting([counts(2, 1, 5), counts(0, 3, 0), counts(1, 0, 0)]),
            7
        );
        // One that was not reached yet has nothing to count, and takes
        // nothing from the others.
        assert_eq!(waiting([counts(2, 1, 0), None, counts(0, 3, 0)]), 6);
        assert_eq!(waiting([None]), 0);
    }

    #[test]
    fn what_a_yard_has_waiting_is_said_in_words() {
        let counts = |mail, decisions, notices| Counts {
            mail,
            decisions,
            notices,
        };
        assert_eq!(counts(0, 0, 0).line(), "nothing waiting");
        assert_eq!(counts(2, 1, 0).line(), "2 mail, 1 decision");
        assert_eq!(counts(1, 0, 1).line(), "1 mail, 1 notice");
        assert_eq!(counts(0, 3, 12).line(), "3 decisions, 12 notices");
    }

    #[test]
    fn the_rail_s_glyphs_carry_the_mail_and_the_decisions() {
        let counts = |mail, decisions, notices| Counts {
            mail,
            decisions,
            notices,
        };
        // Chat carries the unread mail, decisions the open asks: the
        // badge's label with the tooltip's words. None at 0, and each
        // glyph none of the other's.
        assert_eq!(counts(0, 0, 0).rail(Mode::Chat), None);
        assert_eq!(counts(0, 0, 0).rail(Mode::Decisions), None);
        assert_eq!(
            counts(1, 0, 0).rail(Mode::Chat),
            Some(("1".to_string(), "1 mail".to_string()))
        );
        assert_eq!(
            counts(0, 1, 0).rail(Mode::Decisions),
            Some(("1".to_string(), "1 decision".to_string()))
        );
        assert_eq!(counts(1, 0, 0).rail(Mode::Decisions), None);
        assert_eq!(counts(0, 1, 0).rail(Mode::Chat), None);
        // Above nine the badge says 9+, and the tooltip the number.
        assert_eq!(
            counts(10, 0, 0).rail(Mode::Chat),
            Some(("9+".to_string(), "10 mail".to_string()))
        );
        assert_eq!(
            counts(0, 12, 0).rail(Mode::Decisions),
            Some(("9+".to_string(), "12 decisions".to_string()))
        );
        // The notices are no glyph's, and the timetable carries none
        // whatever waits.
        assert_eq!(counts(0, 0, 5).rail(Mode::Chat), None);
        assert_eq!(counts(0, 0, 5).rail(Mode::Decisions), None);
        assert_eq!(counts(3, 2, 9).rail(Mode::Timetable), None);
    }

    #[test]
    fn the_rail_s_dot_is_the_model_s_unless_the_yard_is_away() {
        let state = model::State {
            me: "jo".into(),
            head: 20,
            ..model::State::default()
        };
        let (mut m, _) = Model::new(state, Mode::Chat, None);
        m.adopt_timetable_seen(None, 20);
        // Nothing lit, nothing carried, whatever answers.
        assert!(!rail_dot(Some(&m), false));
        assert!(!rail_dot(Some(&m), true));
        assert!(!rail_dot(None, false));
        // Lit: carried while the yard answers, hidden while it is away.
        let created: api::Event = serde_json::from_value(json!({
            "seq": 21, "kind": "created", "actor": "yardmaster", "bead": "yd-barn",
            "data": {"originator": "jo"},
        }))
        .unwrap();
        let _ = m.event(&created);
        assert!(m.timetable_dot());
        assert!(rail_dot(Some(&m), false));
        assert!(!rail_dot(Some(&m), true));
    }

    /// The yards in the settings: this machine's, as before, and one at an
    /// address that is added by a pairing's code. A wrong code and a
    /// refused address are said and change nothing; a removed device is
    /// said, not asked after, and paired again into the same file.
    #[gpui::test]
    fn the_settings_list_the_yards_and_a_code_pairs_a_new_one(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let token = dir.path().join("footplate/yard-far.token");
        let near = Yard::start();
        a_yard_of_jo(&near);
        let far = Yard::start_tcp();
        a_far_yard_of_jo(&far);
        let env = Env {
            socket: near.socket().to_path_buf(),
            ..Env::default()
        };
        let (view, cx) = opened_at(env, &file, cx);
        // Nothing chosen: this machine's yard, by its socket.
        wait(cx, "this machine's yard", |cx| {
            texts(&view, cx) == ["Shall I land it?"]
        });
        assert_eq!(which_yard(&view, cx), "this machine's yard");
        assert_eq!(open_yard(&view, cx), "this machine");
        assert!(drawn(cx, "switch tile"));
        assert_eq!(far.requests(), 0);

        // The settings list it, say what a pairing gives over a peer link,
        // and ask for nothing until a yard is added.
        cx.simulate_keystrokes("secondary-,");
        click_on(cx, "settings section yards");
        let before_pairing = Settings::read(&file);
        assert!(drawn(cx, "yard row this machine"));
        assert!(drawn(cx, "pairing gives"));
        assert_eq!(
            PAIRING_GIVES,
            "A paired yard is called with this device's own token, so your picks and approvals there count as yours, where over a peer link you only see what the link carries and an approval never crosses."
        );
        assert!(drawn(cx, "add near") && drawn(cx, "add far") && drawn(cx, "add hosted"));
        assert!(!drawn(cx, "yard pair"));
        click_on(cx, "add far");
        assert!(drawn(cx, "yard name") && drawn(cx, "yard address") && drawn(cx, "yard code"));
        assert!(drawn(cx, "yard pair"));

        // The name is typed first. Plain http off this machine is refused
        // with the reason, and nothing is sent anywhere.
        cx.simulate_input("far");
        assert_eq!(
            view.read_with(cx, |v, cx| v.yard_name.read(cx).text().to_string()),
            "far"
        );
        type_in(&view, cx, "far", "http://mac.example.net", "K7QM-2XPD");
        cx.simulate_keystrokes("enter");
        let said = yard_said(&view, cx);
        assert!(
            said.starts_with("http://mac.example.net is refused: plain http"),
            "{said}"
        );
        // The refusal is the line under the fields, nothing was sent, and
        // the fields stay filled for the fix.
        assert!(drawn(cx, "yard said"));
        assert_eq!(far.requests(), 0);
        assert_eq!(Settings::read(&file), before_pairing);
        view.read_with(cx, |v, cx| {
            assert_eq!(
                v.address.read(cx).text().to_string(),
                "http://mac.example.net"
            );
            assert_eq!(v.code.read(cx).text().to_string(), "K7QM-2XPD");
        });
        // No code: one is wanted.
        type_in(&view, cx, "far", far.address(), "");
        click_on(cx, "yard pair");
        assert!(yard_said(&view, cx).starts_with("A code is wanted."));
        // No pairing is open at the yard.
        type_in(&view, cx, "far", far.address(), "K7QM-2XPD");
        click_on(cx, "yard pair");
        wait(cx, "that no pairing is open", |cx| {
            yard_said(&view, cx).starts_with("No pairing is open at this yard")
        });

        // The operator opens one, and the code is typed wrong: the yard
        // says so, and nothing changed.
        far.pair("K7QM-2XPD");
        type_in(&view, cx, "far", far.address(), "WXYZ-2345");
        click_on(cx, "yard pair");
        wait(cx, "that it is not the code", |cx| {
            yard_said(&view, cx).starts_with("That is not the code.")
        });
        assert!(!token.exists());
        assert_eq!(Settings::read(&file), before_pairing);
        assert_eq!(which_yard(&view, cx), "this machine's yard");
        assert_eq!(far.devices(), [crate::fake::TOKEN]);
        assert!(drawn(cx, "yard said"));

        // The right code, here as the pairing's QR code holds it: the
        // window shows that yard, as the user and the device it says.
        type_in(
            &view,
            cx,
            "far",
            &format!("{}#k7qm-2xpd", far.address()),
            "",
        );
        click_on(cx, "yard pair");
        wait(cx, "the yard at the address", |cx| {
            texts(&view, cx) == ["From afar."]
        });
        let here = format!("the yard south at {}, as its device laptop", far.address());
        assert_eq!(which_yard(&view, cx), here);
        assert_eq!(open_yard(&view, cx), "far");
        assert!(yard_said(&view, cx).starts_with("Paired: this is the device laptop of jo"));
        // Its fields are asked for no longer. (By the window's own word:
        // gpui's test keeps the bounds of what an earlier frame drew.)
        assert_eq!(view.read_with(cx, |v, _| v.adding.clone()), None);
        // The yard is kept with the settings after this machine's, as the
        // open one, its token in a file of its own that only its user
        // reads, and nowhere else.
        let kept = Settings::read(&file);
        assert_eq!(
            kept.yards,
            [
                settings::Yard::near(settings::HERE, ""),
                settings::Yard::far("far", far.address(), "yard-far.token")
            ]
        );
        assert_eq!(kept.open, "far");
        let first = far.devices()[1].clone();
        assert_eq!(yard::read_token(&token).unwrap(), first);
        assert_eq!(mode_of(&token), 0o600);
        assert!(
            !std::fs::read_to_string(&file)
                .unwrap()
                .contains("yardr-dev")
        );
        assert_eq!(
            view.read_with(cx, |v, cx| v.code.read(cx).text().to_string()),
            ""
        );
        // Every call there is the device's.
        assert!(
            far.last_request()
                .contains(&format!("Authorization: Bearer {first}\r\n"))
        );

        // The operator removes the device. The window says so, and does
        // not ask again; it offers to pair again.
        far.remove_device(&first);
        wait(cx, "that the device is not let in", |cx| {
            view.read_with(cx, |v, _| v.away == Away::Out)
        });
        let why = view.read_with(cx, |v, _| v.down.clone().unwrap());
        assert!(why.starts_with("This device is no longer let in"), "{why}");
        cx.simulate_keystrokes("escape");
        assert!(!settings_open(&view, cx));
        assert!(drawn(cx, "pair again"));
        click_on(cx, "pair again");
        assert!(settings_open(&view, cx));
        assert!(drawn(cx, "yard pair"));
        assert_eq!(
            view.read_with(cx, |v, _| v.adding.clone()),
            Some(Adding::Again("far".into()))
        );
        // The yard's address is known, so the code is what is typed, and
        // Enter sends it: the token is the same yard's, in the same file.
        far.pair("ABCD-EFGH");
        cx.simulate_input("abcd efgh");
        cx.simulate_keystrokes("enter");
        wait(cx, "the yard again", |cx| {
            texts(&view, cx) == ["From afar."]
        });
        let second = far.devices()[1].clone();
        assert_ne!(second, first);
        assert_eq!(yard::read_token(&token).unwrap(), second);
        assert_eq!(mode_of(&token), 0o600);
        assert_eq!(Settings::read(&file), kept);

        // This machine's yard again: the socket, as before. The far yard
        // and its token stay, to go back to.
        click_on(cx, "yard open this machine");
        wait(cx, "this machine's yard again", |cx| {
            texts(&view, cx) == ["Shall I land it?"]
        });
        assert_eq!(which_yard(&view, cx), "this machine's yard");
        let again = Settings::read(&file);
        assert_eq!(
            (again.open.as_str(), &again.yards),
            (settings::HERE, &kept.yards)
        );
        // And back with no code: the device is paired already.
        click_on(cx, "yard open far");
        wait(cx, "the yard at the address once more", |cx| {
            texts(&view, cx) == ["From afar."]
        });
        assert_eq!(far.devices()[1], second);
        assert_eq!(Settings::read(&file), kept);

        // The next start opens the yard that was open.
        let env = Env {
            socket: near.socket().to_path_buf(),
            ..Env::default()
        };
        let (again, cx) = opened_at(env, &file, cx);
        wait(cx, "the open yard at the next start", |cx| {
            texts(&again, cx) == ["From afar."]
        });
        assert_eq!(which_yard(&again, cx), here);
    }

    /// The settings file of a window paired before there were several
    /// yards, with `yard.token` beside it, opens paired as it was, as one
    /// yard called by its address's host; the next change keeps it so.
    #[gpui::test]
    fn a_settings_file_from_before_opens_paired_as_it_was(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let token = dir.path().join("footplate/yard.token");
        let near = Yard::start();
        a_yard_of_jo(&near);
        let far = Yard::start_tcp();
        a_far_yard_of_jo(&far);
        yard::keep_token(&token, crate::fake::TOKEN).unwrap();
        std::fs::write(
            &file,
            format!(
                "{{\n  \"text\": 14,\n  \"look\": \"auto\",\n  \"remote\": true,\n  \"address\": \"{}\"\n}}\n",
                far.address()
            ),
        )
        .unwrap();
        let env = Env {
            socket: near.socket().to_path_buf(),
            ..Env::default()
        };
        let (view, cx) = opened_at(env, &file, cx);
        wait(cx, "the yard it was paired with", |cx| {
            texts(&view, cx) == ["From afar."]
        });
        assert_eq!(
            which_yard(&view, cx),
            format!("the yard south at {}, as its device laptop", far.address())
        );
        // This machine's yard is in the list beside it now, so it is
        // followed for what waits there; the open one is still the far.
        assert_eq!(open_yard(&view, cx), "127.0.0.1");
        assert!(
            far.last_request()
                .contains(&format!("Authorization: Bearer {}\r\n", crate::fake::TOKEN))
        );
        // The first-run watermark writes the migrated settings; the next
        // change keeps the list the same way.
        let text = std::fs::read_to_string(&file).unwrap();
        assert!(!text.contains("remote") && text.contains("\"timetable_seen\""));
        cx.simulate_keystrokes("secondary-=");
        let kept = Settings::read(&file);
        assert_eq!(
            kept.yards,
            [
                settings::Yard::far("127.0.0.1", far.address(), "yard.token"),
                settings::Yard::near(settings::HERE, "")
            ]
        );
        let text = std::fs::read_to_string(&file).unwrap();
        assert!(
            !text.contains("remote") && text.contains("\"yards\""),
            "{text}"
        );
        assert_eq!(yard::read_token(&token).unwrap(), crate::fake::TOKEN);
    }

    /// Three yards kept with the settings: this machine's, a second
    /// home's by its socket, and a paired one. Their settings file, and the
    /// paired one's token beside it.
    fn three_yards(dir: &std::path::Path, second: &Yard, far: &Yard) -> PathBuf {
        let file = dir.join("footplate/settings.json");
        let set = Settings::default()
            .with_yard(
                None,
                settings::Yard::near("second home", second.socket().to_str().unwrap()),
                None,
            )
            .unwrap()
            .with_yard(
                None,
                settings::Yard::far("far", far.address(), "yard-far.token"),
                Some(&file),
            )
            .unwrap();
        set.write(&file).unwrap();
        yard::keep_token(&dir.join("footplate/yard-far.token"), crate::fake::TOKEN).unwrap();
        file
    }

    /// The tile at the rail's foot names the open yard and switches: a
    /// click or its key opens the list of the yards to the right of the
    /// rail, each with its kind and what waits in it now; a click on a
    /// row, Enter on the row the arrows are on, or a yard's own key from
    /// anywhere opens it, as it stands: every yard is followed from the
    /// start.
    #[gpui::test]
    fn the_tile_switches_between_the_yards_by_click_and_by_key(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let near = Yard::start();
        a_yard_of_jo(&near);
        let second = Yard::start();
        a_second_yard_of_jo(&second);
        let far = Yard::start_tcp();
        a_far_yard_of_jo(&far);
        let file = three_yards(dir.path(), &second, &far);
        let env = Env {
            socket: near.socket().to_path_buf(),
            ..Env::default()
        };
        let (view, cx) = opened_at(env, &file, cx);
        // The first of the list, where none was open before. The others
        // are read too, and say what waits in them.
        wait(cx, "this machine's yard", |cx| {
            texts(&view, cx) == ["Shall I land it?"]
        });
        assert_eq!(open_yard(&view, cx), "this machine");
        wait(cx, "what waits in the other yards", |cx| {
            state_of(&view, cx, "second home") == "2 mail" && state_of(&view, cx, "far") == "1 mail"
        });
        assert!(!drawn(cx, "switcher"));

        // A click on the tile opens the list: each yard, its kind, and
        // its state, in a popover to the right of the rail's foot.
        click_on(cx, "switch tile");
        assert_eq!(switching(&view, cx), Some(0));
        assert!(drawn(cx, "switcher"));
        assert!(drawn(cx, "switch this machine") && drawn(cx, "switch far"));
        let rail = bounds_of(cx, "rail");
        let tile = bounds_of(cx, "switch tile");
        let popover = bounds_of(cx, "switcher");
        assert!(
            rail.right() < popover.left() && popover.left() - rail.right() < px(16.),
            "the list stands off the rail: {popover:?} {rail:?}"
        );
        assert!(
            rail.bottom() - popover.bottom() < px(16.) && tile.top() < popover.bottom(),
            "the list stands off the rail's foot: {popover:?} {tile:?} {rail:?}"
        );
        assert_eq!(state_of(&view, cx, "this machine"), "open");
        let kinds: Vec<&str> = view.read_with(cx, |v, _| {
            v.settings.yards.iter().map(|y| y.kind()).collect()
        });
        assert_eq!(kinds, ["on this machine", "on this machine", "paired"]);
        // A click on a row opens that yard, and it is the one to open at
        // the next start.
        click_on(cx, "switch second home");
        wait(cx, "the second home's yard", |cx| {
            texts(&view, cx) == ["From the second home."]
        });
        assert_eq!(open_yard(&view, cx), "second home");
        assert_eq!(switching(&view, cx), None);
        assert_eq!(Settings::read(&file).open, "second home");
        // What the one that was left has: its mail was read in the open
        // conversation.
        assert_eq!(state_of(&view, cx, "this machine"), "nothing waiting");
        let had = view.read_with(cx, |v, _| Counts::of(v.model.as_ref().unwrap()));
        assert_eq!((had.mail, had.decisions), (1, 0), "{had:?}");

        // The switcher's key opens the list on the open yard; the arrows
        // move and stop at its ends, esc leaves it, Enter opens.
        cx.simulate_keystrokes("secondary-y");
        assert_eq!(switching(&view, cx), Some(1));
        cx.simulate_keystrokes("up up");
        assert_eq!(switching(&view, cx), Some(0));
        cx.simulate_keystrokes("escape");
        assert_eq!(switching(&view, cx), None);
        assert_eq!(texts(&view, cx), ["From the second home."]);
        cx.simulate_keystrokes("secondary-y down down down");
        assert_eq!(switching(&view, cx), Some(2));
        // No key is a card's or the line's while the list has them.
        cx.simulate_keystrokes("x 1");
        assert_eq!(typed(&view, cx), "");
        cx.simulate_keystrokes("enter");
        wait(cx, "the paired yard", |cx| {
            texts(&view, cx) == ["From afar."]
        });
        assert_eq!(open_yard(&view, cx), "far");
        assert_eq!(switching(&view, cx), None);
        assert_eq!(state_of(&view, cx, "second home"), "1 mail");
        // Every call there is the device's, with the token of that yard.
        assert!(
            far.last_request()
                .contains(&format!("Authorization: Bearer {}\r\n", crate::fake::TOKEN))
        );

        // A yard's place in the list is its key, from anywhere: the line
        // has the focus here. A place with no yard opens nothing.
        cx.simulate_input("typed");
        cx.simulate_keystrokes("secondary-1");
        wait(cx, "this machine's yard by its key", |cx| {
            texts(&view, cx) == ["Shall I land it?"]
        });
        assert_eq!(state_of(&view, cx, "far"), "nothing waiting");
        cx.simulate_keystrokes("secondary-9");
        cx.run_until_parked();
        assert_eq!(open_yard(&view, cx), "this machine");
        cx.simulate_keystrokes("secondary-3");
        wait(cx, "the paired yard by its key", |cx| {
            texts(&view, cx) == ["From afar."]
        });
        // What was typed there is there again.
        assert_eq!(typed(&view, cx), "typed");
        assert_eq!(Settings::read(&file).open, "far");
    }

    /// What is written for one yard stays with it across a switch and is
    /// sent only there: the line's text, the attachments and the words of
    /// an ask. A mail that is on its way when another yard is opened goes
    /// to the yard it was written in, and what of it does not go is back
    /// in that yard's draft, never in the open one's. Nothing typed of a
    /// secret outlasts a switch.
    #[gpui::test]
    fn what_is_written_for_one_yard_is_untouched_by_a_switch_and_sent_only_there(
        cx: &mut TestAppContext,
    ) {
        let dir = tempfile::tempdir().unwrap();
        let near = Yard::start();
        a_yard_of_jo(&near);
        near.answer(
            "PutBlob",
            &json!({"result": {"hash": HASH, "type": "image/png", "bytes": 70}}).to_string(),
        );
        let second = Yard::start();
        a_second_yard_of_jo(&second);
        let far = Yard::start_tcp();
        let file = three_yards(dir.path(), &second, &far);
        let env = Env {
            socket: near.socket().to_path_buf(),
            ..Env::default()
        };
        let (view, cx) = opened_at(env, &file, cx);
        wait(cx, "this machine's yard", |cx| {
            texts(&view, cx) == ["Shall I land it?"]
        });
        let mails = |yard: &Yard| -> Vec<String> {
            let asked = yard.asked("Mail");
            asked.iter().map(|args| args.to_string()).collect()
        };

        // A draft for this machine's yardmaster: text, an image, and the
        // words of an ask; and a value half typed in a secret's field.
        cx.simulate_input("For the mac.");
        let image = Image::from_bytes(ImageFormat::Png, png());
        cx.write_to_clipboard(gpui::ClipboardItem::new_image(&image));
        cx.simulate_keystrokes("secondary-v");
        wait(cx, "the image in the draft", |cx| {
            attached(&view, cx) == [(1, PASTED.to_string(), None)]
        });
        let words = (("bead-a".to_string(), 3), "Not yet.".to_string());
        view.update(cx, |v, cx| {
            v.ask_words.insert(words.0.clone(), words.1.clone());
            v.secret
                .update(cx, |field, cx| field.set_text("hunter2", cx));
            v.secret_typed.push("first of two".into());
        });

        // The second home's yard: its line is empty, nothing is attached,
        // no ask has words, and nothing of a secret is anywhere.
        cx.simulate_keystrokes("secondary-2");
        wait(cx, "the second home's yard", |cx| {
            texts(&view, cx) == ["From the second home."]
        });
        assert_eq!(typed(&view, cx), "");
        assert_eq!(attached(&view, cx), []);
        view.read_with(cx, |v, cx| {
            assert!(v.ask_words.is_empty());
            assert_eq!(v.secret.read(cx).text(), "");
            assert!(v.secret_typed.is_empty());
        });
        // What is written here is sent here, and nothing of the other.
        cx.simulate_input("For the second.");
        cx.simulate_keystrokes("enter");
        wait(cx, "the mail in the second home's yard", |cx| {
            let _ = cx;
            second.asked("Mail").len() == 1
        });
        assert!(
            mails(&second)[0].contains("For the second."),
            "{:?}",
            mails(&second)
        );
        assert!(!mails(&second)[0].contains("For the mac."));
        assert_eq!(second.asked("PutBlob").len(), 0);
        assert_eq!(near.asked("Mail").len(), 0);
        cx.simulate_input("Half a thought.");

        // Back: all of the first draft is as it was left.
        cx.simulate_keystrokes("secondary-1");
        wait(cx, "this machine's yard again", |cx| {
            texts(&view, cx) == ["Shall I land it?"]
        });
        assert_eq!(typed(&view, cx), "For the mac.");
        assert_eq!(attached(&view, cx), [(1, PASTED.to_string(), None)]);
        view.read_with(cx, |v, _| {
            assert_eq!(v.ask_words.get(&words.0), Some(&words.1));
            assert!(v.thumbs.contains_key(&1));
        });

        // It is sent, and with the mail on its way the other yard is
        // opened, with text in the line that was typed since: the keys
        // come one after the other before the call's answer is heard. The
        // yard it was written in refuses it.
        near.answer(
            "Mail",
            r#"{"error": {"code": "error", "message": "mail to yardmaster: the yard is full"}}"#,
        );
        cx.simulate_keystrokes("enter s i n c e secondary-2");
        wait(cx, "the second home's yard with a mail on its way", |cx| {
            texts(&view, cx) == ["From the second home."]
        });
        wait(cx, "that it did not go", |cx| {
            notice(&view, cx).starts_with("not sent to yardmaster in this machine: ")
        });
        // It went to the yard it was written in and to no other, and what
        // did not go is in no line and no draft of the open yard.
        assert_eq!(near.asked("Mail").len(), 1);
        assert!(
            mails(&near)[0].contains("For the mac."),
            "{:?}",
            mails(&near)
        );
        assert!(!mails(&near)[0].contains("Half a thought."));
        assert_eq!(typed(&view, cx), "Half a thought.");
        assert_eq!(attached(&view, cx), []);
        assert_eq!(second.asked("Mail").len(), 1);
        assert_eq!(second.asked("PutBlob").len(), 0);

        // Back in its own yard it is in the line again, before what was
        // typed since, with its image.
        cx.simulate_keystrokes("secondary-1");
        wait(cx, "this machine's yard once more", |cx| {
            texts(&view, cx) == ["Shall I land it?"]
        });
        assert_eq!(typed(&view, cx), "For the mac. since");
        assert_eq!(attached(&view, cx), [(1, PASTED.to_string(), None)]);

        // Sent again, and the other yard opened over it: it goes where it
        // was written, and the open yard's line is its own.
        near.answer("Mail", "{}");
        cx.simulate_keystrokes("enter secondary-2");
        wait(cx, "the second home's yard over it", |cx| {
            texts(&view, cx) == ["From the second home."]
        });
        assert_eq!(near.asked("Mail").len(), 2);
        assert!(
            mails(&near)[1].contains("For the mac. since"),
            "{:?}",
            mails(&near)
        );
        assert_eq!(typed(&view, cx), "Half a thought.");
        assert_eq!(notice(&view, cx), "");
        assert_eq!(second.asked("Mail").len(), 1);
        cx.simulate_keystrokes("secondary-1");
        wait(cx, "this machine's yard at last", |cx| {
            texts(&view, cx) == ["Shall I land it?"]
        });
        assert_eq!(typed(&view, cx), "");
        assert_eq!(attached(&view, cx), []);
    }

    #[gpui::test]
    fn a_failed_send_is_not_restored_to_a_new_yard_that_reuses_its_name(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let old = Yard::start_tcp();
        a_far_yard_of_jo(&old);
        old.answer(
            "Mail",
            r#"{"error": {"code": "error", "message": "mail refused"}}"#,
        );
        let replacement = Yard::start_tcp();
        a_far_yard_of_jo(&replacement);
        replacement.answer(
            "UserInbox",
            r#"{"result": {"mail": [{"seq": 32, "from": "yardmaster", "to": "jo", "text": "From the replacement.", "read": false}], "unread": 1, "last": 32, "from": ["yardmaster"]}}"#,
        );
        replacement.answer(
            "Conversation",
            r#"{"result": [{"seq": 32, "at": "2026-10-08T09:30:00Z", "from": "yardmaster", "to": "jo", "text": "From the replacement.", "read": false}]}"#,
        );
        let token = dir.path().join("footplate/yard-far.token");
        yard::keep_token(&token, crate::fake::TOKEN).unwrap();
        let settings = Settings::default()
            .with_yard(
                None,
                settings::Yard::far("far", old.address(), "yard-far.token"),
                Some(&file),
            )
            .unwrap()
            .opening("far");
        settings.write(&file).unwrap();
        let env = Env::default();
        let (view, cx) = opened_at(env, &file, cx);
        wait(cx, "the original yard", |cx| {
            texts(&view, cx) == ["From afar."]
        });

        // Queue a failed send through the old client, then replace that
        // settings entry under the same display name before its answer is
        // handled by the window.
        view.update(cx, |v, cx| {
            assert!(v.open().is_some());
            v.line
                .update(cx, |line, cx| line.set_text("private to old far", cx));
            v.send(cx);
            let (without, _, _) = v.settings.clone().without("far", Some(&file));
            yard::keep_token(&token, crate::fake::TOKEN).unwrap();
            let replacement = without
                .with_yard(
                    None,
                    settings::Yard::far("far", replacement.address(), "yard-far.token"),
                    Some(&file),
                )
                .unwrap()
                .opening("far");
            v.set(replacement, cx);
            v.reopen(cx);
        });

        wait(cx, "the replacement yard", |cx| {
            texts(&view, cx) == ["From the replacement."]
        });
        wait(cx, "the old send refusal", |cx| {
            notice(&view, cx).starts_with(
                "not sent to yardmaster in far: that yard entry was removed or changed",
            )
        });
        assert_eq!(typed(&view, cx), "");
        assert_eq!(old.asked("Mail").len(), 1);
        assert!(replacement.asked("Mail").is_empty());
    }

    /// The words of an answer that is on its way when another yard is
    /// opened, and that its yard refuses, are back with the ask they were
    /// typed for, in its own yard: never in the line of the open one.
    #[gpui::test]
    fn words_a_yard_refused_are_back_with_their_ask_and_not_in_another_yard_s_line(
        cx: &mut TestAppContext,
    ) {
        let dir = tempfile::tempdir().unwrap();
        let near = Yard::start();
        a_yard_of_jo(&near);
        near.answer("UserAsks", &asks_three());
        near.answer("Bead", &bead_three());
        near.answer(
            "AnswerAsk",
            r#"{"error": {"code": "error", "message": "bead-a: the ask is closed"}}"#,
        );
        let second = Yard::start();
        a_second_yard_of_jo(&second);
        let far = Yard::start_tcp();
        let file = three_yards(dir.path(), &second, &far);
        let env = Env {
            socket: near.socket().to_path_buf(),
            ..Env::default()
        };
        let (view, cx) = opened_at(env, &file, cx);
        let on_the_card = |cx: &mut VisualTestContext| {
            to_decisions(&view, cx);
            view.read_with(cx, |v, _| {
                v.model
                    .as_ref()
                    .is_some_and(|m| m.selected() == Some(&Selected::Decision("bead-a".into())))
            })
        };
        wait(cx, "the decision", on_the_card);
        wait(cx, "the bead", |cx| has_bead(&view, cx, "bead-a"));
        cx.run_until_parked();
        // A pick with words, and the other yard opened before the yard's
        // answer to it is heard.
        cx.simulate_keystrokes("escape 2 i");
        cx.simulate_input("because");
        cx.simulate_keystrokes("enter secondary-2");
        wait(cx, "the second home's yard", |cx| {
            texts(&view, cx) == ["From the second home."]
        });
        wait(cx, "that it was not answered", |cx| {
            notice(&view, cx) == "not answered in this machine: bead-a: the ask is closed"
        });
        assert_eq!(near.asked("AnswerAsk").len(), 1);
        assert_eq!(second.asked("AnswerAsk").len(), 0);
        assert_eq!(typed(&view, cx), "");
        view.read_with(cx, |v, _| {
            assert!(v.ask_words.is_empty());
            let kept = &v.kept_words["this machine"];
            assert_eq!(
                kept.get(&("bead-a".to_string(), 3)).map(String::as_str),
                Some("because")
            );
        });
        // Its own yard has them in the line again, on its card.
        cx.simulate_keystrokes("secondary-1");
        wait(cx, "the decision again", on_the_card);
        assert_eq!(typed(&view, cx), "because");
    }

    /// Yards are added and removed in the settings. A name that is taken
    /// is refused before a code is sent anywhere; a new yard's token file
    /// is one no other has; removing a yard deletes its token's file where
    /// it is footplate's alone, and says how the device is removed at the
    /// yard.
    #[gpui::test]
    fn yards_are_added_and_removed_in_the_settings(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let near = Yard::start();
        a_yard_of_jo(&near);
        let second = Yard::start();
        a_second_yard_of_jo(&second);
        let far = Yard::start_tcp();
        a_far_yard_of_jo(&far);
        // This machine's and a paired one, to begin with.
        let file = three_yards(dir.path(), &second, &far);
        let (set, _, _) = Settings::read(&file).without("second home", Some(&file));
        set.write(&file).unwrap();
        let beside = |name: &str| dir.path().join("footplate").join(name);
        let env = Env {
            socket: near.socket().to_path_buf(),
            ..Env::default()
        };
        let (view, cx) = opened_at(env, &file, cx);
        wait(cx, "this machine's yard", |cx| {
            texts(&view, cx) == ["Shall I land it?"]
        });
        cx.simulate_keystrokes("secondary-,");
        click_on(cx, "settings section yards");
        let set = Settings::read(&file);

        // A second home's yard, by its socket: no code, and it is opened.
        click_on(cx, "add near");
        assert!(drawn(cx, "yard name") && drawn(cx, "yard socket"));
        view.update(cx, |v, cx| {
            v.yard_name.update(cx, |line, cx| line.set_text("far", cx));
            let socket = second.socket().to_str().unwrap().to_string();
            v.socket.update(cx, |line, cx| line.set_text(&socket, cx));
        });
        // The name is another yard's: said, and nothing changed.
        click_on(cx, "yard pair");
        assert!(
            yard_said(&view, cx).starts_with("There is a yard called far already"),
            "{}",
            yard_said(&view, cx)
        );
        assert_eq!(Settings::read(&file), set);
        view.update(cx, |v, cx| {
            v.yard_name
                .update(cx, |line, cx| line.set_text("second home", cx));
        });
        click_on(cx, "yard pair");
        wait(cx, "the second home's yard", |cx| {
            texts(&view, cx) == ["From the second home."]
        });
        let kept = Settings::read(&file);
        assert_eq!(
            kept.yards[2],
            settings::Yard::near("second home", second.socket().to_str().unwrap())
        );
        assert_eq!(kept.open, "second home");

        // A yard at an address under a name that is taken: refused before
        // the code is sent, which would use it up.
        far.pair("K7QM-2XPD");
        click_on(cx, "add far");
        type_in(&view, cx, "second home", far.address(), "K7QM-2XPD");
        let before = far.requests();
        click_on(cx, "yard pair");
        assert!(yard_said(&view, cx).starts_with("There is a yard called second home already"));
        cx.run_until_parked();
        assert_eq!(far.requests(), before);
        assert!(far.pairing_open());
        // Under its own name it is paired, into a file no other yard has:
        // the name's own is the yard far's.
        type_in(&view, cx, "FAR", far.address(), "K7QM-2XPD");
        click_on(cx, "yard pair");
        wait(cx, "the pairing", |cx| {
            yard_said(&view, cx).starts_with("Paired")
        });
        wait(cx, "the yard that was paired", |cx| {
            texts(&view, cx) == ["From afar."]
        });
        let kept = Settings::read(&file);
        assert_eq!(
            kept.yards[3],
            settings::Yard::far("FAR", far.address(), "yard-far-2.token")
        );
        assert_eq!(
            yard::read_token(&beside("yard-far-2.token")).unwrap(),
            far.devices()[1]
        );
        assert_eq!(
            yard::read_token(&beside("yard-far.token")).unwrap(),
            crate::fake::TOKEN
        );

        // Removing the open yard: its token's file goes with it, the
        // other's stays, the settings say the command that removes the
        // device at the yard, and the first of the list is opened.
        click_on(cx, "yard remove FAR");
        let said = yard_said(&view, cx);
        assert!(
            said.starts_with(&format!(
                "FAR is removed, and its token's file {} with it.",
                beside("yard-far-2.token").display()
            )),
            "{said}"
        );
        assert!(said.ends_with("yardr user device rm jo laptop"), "{said}");
        assert!(!beside("yard-far-2.token").exists());
        assert!(beside("yard-far.token").exists());
        wait(cx, "the first yard of the list", |cx| {
            texts(&view, cx) == ["Shall I land it?"]
        });
        let kept = Settings::read(&file);
        assert_eq!(kept.yards.len(), 3);
        assert_eq!(kept.opened().name, settings::HERE);
        // A yard that is not open is removed too, and one of this machine
        // has no token to say anything of.
        click_on(cx, "yard remove second home");
        assert_eq!(
            yard_said(&view, cx),
            "second home is removed from the list. Its yard is as it was."
        );
        // Who the device is at a yard that is not open is known too: it
        // is followed, and said so when it was read.
        wait(cx, "the paired yard to be read", |cx| {
            state_of(&view, cx, "far") == "1 mail"
        });
        click_on(cx, "yard remove far");
        let said = yard_said(&view, cx);
        assert!(said.ends_with("yardr user device rm jo laptop"), "{said}");
        assert!(!beside("yard-far.token").exists());
        assert_eq!(
            Settings::read(&file).yards,
            [settings::Yard::near(settings::HERE, "")]
        );
        assert_eq!(texts(&view, cx), ["Shall I land it?"]);
    }

    /// A pairing writes the address the code went to under the token: the
    /// file is of that yard from the moment it is there.
    #[gpui::test]
    fn a_pairing_writes_the_yard_s_address_with_the_token(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let token = dir.path().join("footplate/yard-far.token");
        let near = Yard::start();
        a_yard_of_jo(&near);
        let far = Yard::start_tcp();
        a_far_yard_of_jo(&far);
        far.pair("K7QM-2XPD");
        let env = Env {
            socket: near.socket().to_path_buf(),
            ..Env::default()
        };
        let (view, cx) = opened_at(env, &file, cx);
        wait(cx, "this machine's yard", |cx| {
            texts(&view, cx) == ["Shall I land it?"]
        });
        cx.simulate_keystrokes("secondary-,");
        click_on(cx, "settings section yards");
        click_on(cx, "add far");
        type_in(&view, cx, "far", far.address(), "K7QM-2XPD");
        click_on(cx, "yard pair");
        wait(cx, "the pairing", |cx| {
            yard_said(&view, cx).starts_with("Paired")
        });
        assert_eq!(
            std::fs::read_to_string(&token).unwrap(),
            format!(
                "{}\n!footplate-token-v1\n{}\n",
                far.devices()[1],
                Address::parse(far.address()).unwrap()
            )
        );
        assert_eq!(mode_of(&token), 0o600);
        // Nothing else is left beside it.
        assert_eq!(
            std::fs::read_dir(dir.path().join("footplate"))
                .unwrap()
                .count(),
            2
        );
    }

    /// A token file typed by hand that cannot be written is found before
    /// the code is sent: the yard is asked nothing, adds no device, and
    /// its pairing stays open for the code.
    #[gpui::test]
    fn a_token_file_that_cannot_be_written_keeps_the_code_from_the_yard(cx: &mut TestAppContext) {
        // No file mode holds root: the directory below that cannot be
        // written for another user takes the token here.
        if yard::running_as_root() {
            eprintln!("skipped: root (euid 0) is not held by a file's mode");
            return;
        }
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let tokens = dir.path().join("tokens");
        let token = tokens.join("yard.token");
        let near = Yard::start();
        a_yard_of_jo(&near);
        let far = Yard::start_tcp();
        a_far_yard_of_jo(&far);
        far.pair("K7QM-2XPD");
        Settings::default()
            .with_yard(
                None,
                settings::Yard::far("far", far.address(), token.to_str().unwrap()),
                Some(&file),
            )
            .unwrap()
            .write(&file)
            .unwrap();
        let env = Env {
            socket: near.socket().to_path_buf(),
            ..Env::default()
        };
        let (view, cx) = opened_at(env, &file, cx);
        wait(cx, "this machine's yard", |cx| {
            texts(&view, cx) == ["Shall I land it?"]
        });
        let pair = |cx: &mut VisualTestContext| {
            view.update_in(cx, |v, window, cx| {
                v.pair_again(Some("far".into()), window, cx);
                v.code.update(cx, |line, cx| line.set_text("K7QM-2XPD", cx));
                v.pair(cx);
            });
        };
        let unasked = |cx: &mut VisualTestContext| {
            assert_eq!(far.requests(), 0);
            assert_eq!(far.devices(), [crate::fake::TOKEN]);
            assert!(far.pairing_open());
            assert_eq!(which_yard(&view, cx), "this machine's yard");
        };

        // A directory where the token's file would be.
        std::fs::create_dir_all(&token).unwrap();
        pair(cx);
        wait(cx, "that a directory is no token file", |cx| {
            yard_said(&view, cx).contains("is not a regular file")
        });
        unasked(cx);
        assert!(token.is_dir());
        // The refusal is the line under the fields, and the code stays for
        // the pairing once the file can be written.
        assert!(drawn(cx, "yard said"));
        view.read_with(cx, |v, cx| {
            assert_eq!(v.code.read(cx).text().to_string(), "K7QM-2XPD");
        });

        // A file where its directory would be.
        std::fs::remove_dir_all(&tokens).unwrap();
        std::fs::write(&tokens, "").unwrap();
        pair(cx);
        wait(cx, "that the file cannot be checked", |cx| {
            yard_said(&view, cx).contains("cannot be checked")
        });
        unasked(cx);

        // A directory that cannot be written to, and nothing is left in it.
        std::fs::remove_file(&tokens).unwrap();
        std::fs::create_dir(&tokens).unwrap();
        let mode = |mode| {
            use std::os::unix::fs::PermissionsExt;
            std::fs::set_permissions(&tokens, std::fs::Permissions::from_mode(mode)).unwrap();
        };
        mode(0o500);
        pair(cx);
        wait(cx, "that the directory cannot be written to", |cx| {
            !view.read_with(cx, |v, _| v.pairing) && !yard_said(&view, cx).is_empty()
        });
        let said = yard_said(&view, cx);
        assert!(
            said.starts_with(&format!(
                "The token file {} cannot be written (",
                token.display()
            )) && said.contains("The code was not sent"),
            "{said}"
        );
        unasked(cx);
        mode(0o700);
        assert_eq!(std::fs::read_dir(&tokens).unwrap().count(), 0);

        // The same code pairs once the file can be written.
        pair(cx);
        wait(cx, "the yard that was paired", |cx| {
            texts(&view, cx) == ["From afar."]
        });
        assert_eq!(yard::read_token(&token).unwrap(), far.devices()[1]);
        assert_eq!(std::fs::read_dir(&tokens).unwrap().count(), 1);
    }

    #[gpui::test]
    fn pairing_keeps_settings_changed_while_the_code_is_away(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let near = Yard::start();
        a_yard_of_jo(&near);
        let far = Yard::start_tcp();
        a_far_yard_of_jo(&far);
        far.pair("K7QM-2XPD");
        let env = Env {
            socket: near.socket().to_path_buf(),
            ..Env::default()
        };
        let (view, cx) = opened_at(env, &file, cx);
        wait(cx, "this machine's yard", |cx| {
            texts(&view, cx) == ["Shall I land it?"]
        });
        cx.simulate_keystrokes("secondary-,");
        click_on(cx, "settings section yards");
        click_on(cx, "add far");
        type_in(&view, cx, "far", far.address(), "K7QM-2XPD");

        // Pairing runs away from the window. A settings change made before
        // its answer must be kept with the new yard.
        view.update(cx, |v, cx| {
            v.pair(cx);
            v.set(
                Settings {
                    text: 16,
                    ..v.settings.clone()
                },
                cx,
            );
        });
        wait(cx, "the paired yard", |cx| {
            texts(&view, cx) == ["From afar."]
        });
        assert_eq!(Settings::read(&file).text, 16);
        assert_eq!(Settings::read(&file).opened().name, "far");
        assert_eq!(far.devices().len(), 2);
    }

    /// `FOOTPLATE_YARD` and `FOOTPLATE_TOKEN_FILE` name the one yard of a
    /// run: the window has no switcher and the settings no list, and a
    /// pairing there writes the environment's file.
    #[gpui::test]
    fn the_environment_s_yard_is_the_one_yard_of_the_window(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let token = dir.path().join("mac.token");
        yard::keep_token(&token, crate::fake::TOKEN).unwrap();
        let near = Yard::start();
        a_yard_of_jo(&near);
        let second = Yard::start();
        a_second_yard_of_jo(&second);
        let far = Yard::start_tcp();
        a_far_yard_of_jo(&far);
        let file = three_yards(dir.path(), &second, &far);
        let env = Env {
            yard: Some(far.address().to_string()),
            token_file: Some(token.clone()),
            socket: near.socket().to_path_buf(),
        };
        let (view, cx) = opened_at(env, &file, cx);
        wait(cx, "the environment's yard", |cx| {
            texts(&view, cx) == ["From afar."]
        });
        assert_eq!(near.requests(), 0);
        assert!(which_yard(&view, cx).starts_with("the yard south at http://127.0.0.1"));
        // No switcher: no tile, and no key opens another yard.
        assert!(!drawn(cx, "switch tile"));
        assert_eq!(switching(&view, cx), None);
        cx.simulate_keystrokes("secondary-y secondary-1 secondary-2");
        cx.run_until_parked();
        assert_eq!(switching(&view, cx), None);
        assert_eq!(texts(&view, cx), ["From afar."]);
        assert_eq!((near.requests(), second.requests()), (0, 0));
        // Nor do the settings list the yards they keep.
        cx.simulate_keystrokes("secondary-,");
        click_on(cx, "settings section yards");
        let kept = std::fs::read_to_string(&file).unwrap();
        assert!(drawn(cx, "yard again"));
        view.update_in(cx, |v, window, cx| {
            v.add_yard(Adding::Far, window, cx);
            v.remove_yard("far", cx);
        });
        assert_eq!(view.read_with(cx, |v, _| v.adding.clone()), None);
        // A pairing there goes to the environment's address, and its token
        // into the environment's file: no yard's of the settings.
        click_on(cx, "yard again");
        far.pair("K7QM-2XPD");
        view.update(cx, |v, cx| {
            v.code.update(cx, |line, cx| line.set_text("K7QM-2XPD", cx));
        });
        click_on(cx, "yard pair");
        wait(cx, "the pairing", |cx| {
            yard_said(&view, cx).starts_with("Paired")
        });
        assert_eq!(yard::read_token(&token).unwrap(), far.devices()[1]);
        assert_eq!(
            yard::read_token(&dir.path().join("footplate/yard-far.token")).unwrap(),
            crate::fake::TOKEN
        );
        assert!(!dir.path().join("footplate/yard.token").exists());
        assert_eq!(std::fs::read_to_string(&file).unwrap(), kept);
    }

    /// Under `FOOTPLATE_YARD` without `FOOTPLATE_TOKEN_FILE`, where the
    /// token's file is a listed yard's, a pairing is refused before its
    /// code is sent, saying which yard and file and that the environment
    /// names another: the listed yard stays paired, and without the
    /// environment it opens as it was.
    #[gpui::test]
    fn pairing_under_the_environment_refuses_a_listed_yard_s_token_file(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let token = dir.path().join("footplate/yard.token");
        let near = Yard::start();
        a_yard_of_jo(&near);
        let far_a = Yard::start_tcp();
        a_far_yard_of_jo(&far_a);
        let far_b = Yard::start_tcp();
        a_far_yard_of_jo(&far_b);
        // A settings file from before there were several yards, paired
        // with its yard: its token is in `yard.token` beside it.
        std::fs::create_dir_all(file.parent().unwrap()).unwrap();
        std::fs::write(
            &file,
            format!(
                "{{\n  \"remote\": true,\n  \"address\": \"{}\"\n}}\n",
                far_a.address()
            ),
        )
        .unwrap();
        let address_a = Address::parse(far_a.address()).unwrap();
        yard::token_place(&token)
            .unwrap()
            .keep(crate::fake::TOKEN, &address_a)
            .unwrap();
        let kept = std::fs::read(&token).unwrap();

        // With the environment naming another yard, the token's file is
        // the listed yard's: the yard is not opened, and nothing is sent
        // to either.
        let env = Env {
            yard: Some(far_b.address().to_string()),
            socket: near.socket().to_path_buf(),
            ..Env::default()
        };
        let (view, cx) = opened_at(env, &file, cx);
        cx.run_until_parked();
        let (why, away) = view.read_with(cx, |v, _| (v.down.clone().unwrap(), v.away));
        assert!(why.contains("share one token file"), "{why}");
        assert_eq!(away, Away::Stopped);
        assert_eq!((far_a.requests(), far_b.requests()), (0, 0));

        // Pairing again there is refused the same way: the code is not
        // spent, and the listed yard's token is untouched.
        cx.simulate_keystrokes("secondary-,");
        click_on(cx, "settings section yards");
        click_on(cx, "yard again");
        far_b.pair("K7QM-2XPD");
        view.update(cx, |v, cx| {
            v.code.update(cx, |line, cx| line.set_text("K7QM-2XPD", cx));
        });
        click_on(cx, "yard pair");
        cx.run_until_parked();
        let said = yard_said(&view, cx);
        assert!(
            said.contains(&format!(
                "the listed yard {} at",
                settings::host_of(far_a.address())
            )) && said.contains("FOOTPLATE_TOKEN_FILE"),
            "{said}"
        );
        assert!(far_b.pairing_open());
        assert_eq!((far_a.requests(), far_b.requests()), (0, 0));
        assert_eq!(std::fs::read(&token).unwrap(), kept);

        // Without the environment the listed yard opens paired, as it was.
        let env = Env {
            socket: near.socket().to_path_buf(),
            ..Env::default()
        };
        let (view, cx) = opened_at(env, &file, cx);
        wait(cx, "the listed yard, still paired", |cx| {
            texts(&view, cx) == ["From afar."]
        });
    }

    /// A yard that cannot be opened is said why, and not tried: plain http
    /// off this machine, and a token file open to others. The settings
    /// are there to open another.
    #[gpui::test]
    fn a_yard_that_is_refused_is_said_why_and_not_tried(cx: &mut TestAppContext) {
        use std::os::unix::fs::PermissionsExt;
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let token = dir.path().join("mac.token");
        yard::keep_token(&token, crate::fake::TOKEN).unwrap();
        let near = Yard::start();
        a_yard_of_jo(&near);
        let far = Yard::start_tcp();
        a_far_yard_of_jo(&far);
        let env = |yard: &str| Env {
            yard: Some(yard.to_string()),
            token_file: Some(token.clone()),
            socket: near.socket().to_path_buf(),
        };

        let (view, cx) = opened_at(env("http://mac.example.net:8790"), &file, cx);
        cx.run_until_parked();
        let (why, away) = view.read_with(cx, |v, _| (v.down.clone().unwrap(), v.away));
        assert!(
            why.starts_with("http://mac.example.net:8790 is refused: plain http"),
            "{why}"
        );
        assert_eq!(away, Away::Stopped);
        assert!(drawn(cx, "settings"));
        assert!(!drawn(cx, "pair again"));
        cx.simulate_keystrokes("secondary-,");
        click_on(cx, "settings section yards");
        assert!(drawn(cx, "yard again"));

        // The token's file is readable by others: refused before anything
        // is sent with it.
        std::fs::set_permissions(&token, std::fs::Permissions::from_mode(0o644)).unwrap();
        let (view, cx) = opened_at(env(far.address()), &file, cx);
        cx.run_until_parked();
        let (why, away) = view.read_with(cx, |v, _| (v.down.clone().unwrap(), v.away));
        assert!(why.contains("is open to others (mode 0644)"), "{why}");
        assert_eq!(away, Away::Stopped);
        assert_eq!(far.requests(), 0);
        assert_eq!(near.requests(), 0);
    }

    /// A yard of the settings that cannot be opened leaves the others to
    /// open: its key and the settings' row do, from where it says why.
    #[gpui::test]
    fn another_yard_is_opened_from_one_that_cannot_be(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let near = Yard::start();
        a_yard_of_jo(&near);
        let second = Yard::start();
        a_second_yard_of_jo(&second);
        let far = Yard::start_tcp();
        a_far_yard_of_jo(&far);
        let file = three_yards(dir.path(), &second, &far);
        // The paired yard was open last, and its token is gone.
        Settings::read(&file).opening("far").write(&file).unwrap();
        std::fs::remove_file(dir.path().join("footplate/yard-far.token")).unwrap();
        let env = Env {
            socket: near.socket().to_path_buf(),
            ..Env::default()
        };
        let (view, cx) = opened_at(env, &file, cx);
        cx.run_until_parked();
        let (why, away) = view.read_with(cx, |v, _| (v.down.clone().unwrap(), v.away));
        assert!(why.starts_with("This device has no token"), "{why}");
        assert_eq!(away, Away::Stopped);
        assert_eq!(far.requests(), 0);
        cx.simulate_keystrokes("secondary-2");
        wait(cx, "the second home's yard", |cx| {
            texts(&view, cx) == ["From the second home."]
        });
        // And back to it, as the one that still cannot be opened.
        cx.simulate_keystrokes("secondary-,");
        click_on(cx, "settings section yards");
        click_on(cx, "yard open far");
        cx.run_until_parked();
        assert!(view.read_with(cx, |v, _| v.down.is_some()));
        assert_eq!(open_yard(&view, cx), "far");
    }

    /// The away screen's first line, as it is drawn.
    fn away_why(view: &Entity<Footplate>, cx: &mut VisualTestContext) -> String {
        view.read_with(cx, |v, _| v.away_why().unwrap_or_default())
    }

    /// A yard that is not reached says so with its short why, in the
    /// switcher's row and where it is open: one that is stopped and one
    /// away from the network, "nothing answers"; one that no longer lets
    /// the device in, "pair again". One that was read before it went away
    /// stays as last seen, with the quiet line in the status row; the
    /// away screen is for yards never reached. The rail stays with the
    /// switcher, so another yard is opened from there and never through
    /// the settings, and the yard that answers has all that was its.
    #[gpui::test]
    fn a_yard_that_is_not_reached_says_why_and_the_switcher_leaves_it(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let near = Yard::start();
        a_yard_of_jo(&near);
        let second = Yard::start();
        a_second_yard_of_jo(&second);
        let far = Yard::start_tcp();
        a_far_yard_of_jo(&far);
        let shop = Yard::start_tcp();
        let file = three_yards(dir.path(), &second, &far);
        Settings::read(&file)
            .with_yard(
                None,
                settings::Yard::far("shop", shop.address(), "yard-shop.token"),
                Some(&file),
            )
            .unwrap()
            .write(&file)
            .unwrap();
        yard::keep_token(
            &dir.path().join("footplate/yard-shop.token"),
            crate::fake::TOKEN,
        )
        .unwrap();
        let env = Env {
            socket: near.socket().to_path_buf(),
            ..Env::default()
        };
        let (view, cx) = opened_at(env, &file, cx);
        wait(cx, "this machine's yard", |cx| {
            texts(&view, cx) == ["Shall I land it?"]
        });
        assert_eq!(open_yard(&view, cx), "this machine");
        cx.simulate_input("kept");
        // The others are followed too, and the two that answer were read.
        wait(cx, "what waits in the yards that answer", |cx| {
            state_of(&view, cx, "second home") == "2 mail" && state_of(&view, cx, "far") == "1 mail"
        });

        // The second home's yard is stopped, the shop is away from the
        // network, and the far yard's operator removed this device, one of
        // two.
        let socket = second.socket().to_path_buf();
        second.stop();
        shop.stop();
        far.add_device("yardr-dev-phone");
        far.remove_device(crate::fake::TOKEN);
        let down = |view: &Entity<Footplate>, cx: &mut VisualTestContext, start: &str| {
            view.read_with(cx, |v, _| {
                v.down.as_deref().is_some_and(|why| why.starts_with(start))
            })
        };

        // The stopped yard was read before it stopped, so it stays as
        // last seen: its rows, its short why in the switcher's row, and
        // the quiet line in the status row. No away screen: that is for
        // a yard never reached.
        cx.simulate_keystrokes("secondary-2");
        wait(cx, "that the second home's yard is stopped", |cx| {
            down(&view, cx, "No yard: nothing answers at the yard's socket")
        });
        assert_eq!(
            state_of(&view, cx, "second home"),
            "not reached: nothing answers"
        );
        assert!(view.read_with(cx, |v, _| v.reconnecting()));
        assert!(drawn(cx, "switch tile") && drawn(cx, "rows"));
        assert!(drawn(cx, "reconnecting"));
        assert_eq!(view.read_with(cx, |v, _| v.away), Away::Trying);
        // What the yard that answers has is as it was left.
        assert_eq!(state_of(&view, cx, "this machine"), "nothing waiting");

        // The tile is the switcher there too: a click lists the yards,
        // the arrows move, and Enter opens the one away from the network.
        click_on(cx, "switch tile");
        assert_eq!(switching(&view, cx), Some(1));
        assert!(drawn(cx, "switcher") && drawn(cx, "switch this machine"));
        cx.simulate_keystrokes("down down enter");
        wait(cx, "that nothing answers at the shop", |cx| {
            down(&view, cx, "No yard: nothing answers at the yard's address")
        });
        assert_eq!(away_why(&view, cx), "shop · nothing answers");
        assert_eq!(state_of(&view, cx, "shop"), "not reached: nothing answers");
        // The one that was left is said as it was left.
        assert_eq!(
            state_of(&view, cx, "second home"),
            "not reached: nothing answers"
        );

        // The switcher's key from a yard that is away, to the one that no
        // longer lets the device in: that is not asked again.
        cx.simulate_keystrokes("secondary-y");
        assert_eq!(switching(&view, cx), Some(3));
        cx.simulate_keystrokes("up enter");
        wait(cx, "that the device is not let in", |cx| {
            view.read_with(cx, |v, _| v.away == Away::Out)
        });
        assert_eq!(away_why(&view, cx), "far · pair again");
        assert_eq!(state_of(&view, cx, "far"), "not reached: pair again");
        assert!(drawn(cx, "away why") && drawn(cx, "pair again"));
        // Esc leaves the list, and the yard stays as it is.
        cx.simulate_keystrokes("secondary-y");
        assert!(drawn(cx, "switcher"));
        cx.simulate_keystrokes("escape");
        assert_eq!(switching(&view, cx), None);
        assert_eq!(open_yard(&view, cx), "far");

        // Back to the yard that answers by a click on its row, with no
        // settings: what was typed there is in its line, and the three
        // that were not reached are said so, each with its own why.
        click_on(cx, "switch tile");
        click_on(cx, "switch this machine");
        wait(cx, "this machine's yard again", |cx| {
            texts(&view, cx) == ["Shall I land it?"]
        });
        assert!(!settings_open(&view, cx));
        assert_eq!(typed(&view, cx), "kept");
        assert_eq!(open_yard(&view, cx), "this machine");
        assert_eq!(state_of(&view, cx, "this machine"), "open");
        assert_eq!(
            state_of(&view, cx, "second home"),
            "not reached: nothing answers"
        );
        assert_eq!(state_of(&view, cx, "shop"), "not reached: nothing answers");
        assert_eq!(state_of(&view, cx, "far"), "not reached: pair again");
        // (By the window's own word: gpui's test keeps the bounds of what
        // an earlier frame drew.)
        assert_eq!(view.read_with(cx, |v, _| v.down.clone()), None);

        // The stopped yard is started: it is asked again by itself, with
        // no switch to it, and is said not reached no longer, there or
        // when it is opened and left.
        let second = Yard::start_at(&socket);
        a_second_yard_of_jo(&second);
        wait(cx, "the second home's yard to answer by itself", |cx| {
            state_of(&view, cx, "second home") == "2 mail"
        });
        assert_eq!(open_yard(&view, cx), "this machine");
        cx.simulate_keystrokes("secondary-2");
        wait(cx, "the second home's yard", |cx| {
            texts(&view, cx) == ["From the second home."]
        });
        assert_eq!(open_yard(&view, cx), "second home");
        assert_eq!(state_of(&view, cx, "second home"), "open");
        cx.simulate_keystrokes("secondary-1");
        wait(cx, "this machine's yard once more", |cx| {
            texts(&view, cx) == ["Shall I land it?"]
        });
        assert_eq!(state_of(&view, cx, "second home"), "1 mail");
    }

    /// A hosted yard whose session the edge stops letting in: the window
    /// says to sign in again, and does not ask again; pairing again is not
    /// offered, since the device is still paired.
    #[gpui::test]
    fn a_hosted_yard_whose_session_is_out_says_to_sign_in_again(cx: &mut TestAppContext) {
        use crate::fake::{Router, SESSION};

        let dir = tempfile::tempdir().unwrap();
        let near = Yard::start();
        a_yard_of_jo(&near);
        let far = Yard::start_tcp();
        a_far_yard_of_jo(&far);
        let edge = Router::start(&far, SESSION);
        let file = dir.path().join("footplate/settings.json");
        Settings::default()
            .with_yard(
                None,
                settings::Yard::hosted(
                    "south",
                    edge.address(),
                    "yard-south.token",
                    "yard-south.session",
                ),
                Some(&file),
            )
            .unwrap()
            .write(&file)
            .unwrap();
        yard::keep_token(
            &dir.path().join("footplate/yard-south.token"),
            crate::fake::TOKEN,
        )
        .unwrap();
        yard::keep_session_token(&dir.path().join("footplate/yard-south.session"), SESSION)
            .unwrap();
        let env = Env {
            socket: near.socket().to_path_buf(),
            ..Env::default()
        };
        let (view, cx) = opened_at(env, &file, cx);
        // This machine's yard is open; the hosted one is followed too, and
        // read through the edge.
        wait(cx, "this machine's yard", |cx| {
            texts(&view, cx) == ["Shall I land it?"]
        });
        wait(cx, "what waits in the hosted yard", |cx| {
            state_of(&view, cx, "south") == "1 mail"
        });

        // The session is revoked at the edge: the hosted yard is said with
        // signing in again as what to do, there and where it is opened.
        edge.revoke(SESSION);
        wait(cx, "that the session is not signed in", |cx| {
            state_of(&view, cx, "south") == "not reached: sign in again"
        });
        click_on(cx, "switch tile");
        click_on(cx, "switch south");
        wait(cx, "the hosted yard signed out", |cx| {
            view.read_with(cx, |v, _| v.away == Away::SignedOut)
        });
        let why = view.read_with(cx, |v, _| v.down.clone().unwrap());
        assert!(
            why.starts_with("This session is no longer signed in"),
            "{why}"
        );
        assert_eq!(open_yard(&view, cx), "south");
        assert_eq!(away_why(&view, cx), "south · sign in again");
        assert!(drawn(cx, "away why"));
        assert!(!drawn(cx, "pair again"));
    }

    /// Pairing a hosted yard of the list again: the session rides beside
    /// the code, and the yard opens as the new device.
    #[gpui::test]
    fn pairing_a_hosted_yard_again_sends_the_session_beside_the_code(cx: &mut TestAppContext) {
        use crate::fake::{Router, SESSION};

        let dir = tempfile::tempdir().unwrap();
        let near = Yard::start();
        a_yard_of_jo(&near);
        let far = Yard::start_tcp();
        a_far_yard_of_jo(&far);
        let edge = Router::start(&far, SESSION);
        let file = dir.path().join("footplate/settings.json");
        let token = dir.path().join("footplate/yard-south.token");
        Settings::default()
            .with_yard(
                None,
                settings::Yard::hosted(
                    "south",
                    edge.address(),
                    "yard-south.token",
                    "yard-south.session",
                ),
                Some(&file),
            )
            .unwrap()
            .opening("south")
            .write(&file)
            .unwrap();
        yard::keep_token(&token, crate::fake::TOKEN).unwrap();
        yard::keep_session_token(&dir.path().join("footplate/yard-south.session"), SESSION)
            .unwrap();
        let env = Env {
            socket: near.socket().to_path_buf(),
            ..Env::default()
        };
        let (view, cx) = opened_at(env, &file, cx);
        wait(cx, "the hosted yard's conversations", |cx| {
            texts(&view, cx) == ["From afar."]
        });

        // The operator removes the device; the session stands. The window
        // offers to pair again, and the code goes with the session: the
        // yard answers only a pairing that carries one. The token is the
        // same yard's, in the same file.
        far.add_device("yardr-dev-phone");
        far.remove_device(crate::fake::TOKEN);
        wait(cx, "that the device is not let in", |cx| {
            view.read_with(cx, |v, _| v.away == Away::Out)
        });
        // The away screen's own button stands clear of the ways, and its
        // centre pairs this yard again: not a way, and no settings first.
        let (way, again) = (bounds_of(cx, "way far"), bounds_of(cx, "pair again"));
        assert!(again.top() >= way.bottom(), "{again:?} {way:?}");
        click_on(cx, "pair again");
        assert!(settings_open(&view, cx));
        assert!(drawn(cx, "yard pair"));
        assert_eq!(
            view.read_with(cx, |v, _| v.adding.clone()),
            Some(Adding::Again("south".into()))
        );
        far.pair("ABCD-EFGH");
        cx.simulate_input("abcd efgh");
        cx.simulate_keystrokes("enter");
        wait(cx, "the pairing", |cx| {
            yard_said(&view, cx).starts_with("Paired:")
        });
        wait(cx, "the yard again", |cx| {
            texts(&view, cx) == ["From afar."] && view.read_with(cx, |v, _| v.down.is_none())
        });
        assert_ne!(yard::read_token(&token).unwrap(), crate::fake::TOKEN);
        assert_eq!(mode_of(&token), 0o600);
    }

    /// From no yard, the hosted road ends in the yard's conversations:
    /// the fourth way signs the Kratos account in, the session is kept
    /// as the device's is, and the pair-by-code road comes next, with
    /// the signed-in account under the yard's name. No terminal, and no
    /// pasted token anywhere.
    #[gpui::test]
    fn opening_a_hosted_yard_signs_in_then_pairs_and_shows_its_conversations(
        cx: &mut TestAppContext,
    ) {
        use crate::fake::{KRATOS_EMAIL, KRATOS_PASSWORD, Router};

        let dir = tempfile::tempdir().unwrap();
        let far = Yard::start_tcp();
        a_far_yard_of_jo(&far);
        // A session nobody holds: the only one that works is minted by
        // signing in.
        let edge = Router::start(&far, "kratos-dev-other");
        edge.delay_logins(Duration::from_millis(150));
        let file = dir.path().join("footplate/settings.json");
        let session = dir.path().join("footplate/yard-south.session");
        let token = dir.path().join("footplate/yard-south.token");
        let (view, cx) = no_yard(dir.path(), cx);

        // The fourth way, with the origin and the account's email and
        // password to type.
        click_on(cx, "way hosted");
        assert_eq!(
            view.read_with(cx, |v, _| v.adding.clone()),
            Some(Adding::Hosted)
        );
        assert!(
            drawn(cx, "yard name")
                && drawn(cx, "yard address")
                && drawn(cx, "yard email")
                && drawn(cx, "yard password")
                && drawn(cx, "yard sign in")
        );
        // An email and a password are wanted, before anything is sent.
        type_sign_in(&view, cx, "south", edge.address(), "", "");
        cx.simulate_keystrokes("enter");
        assert!(yard_said(&view, cx).starts_with("An email is wanted:"));
        type_sign_in(&view, cx, "south", edge.address(), KRATOS_EMAIL, "");
        click_on(cx, "yard sign in");
        assert!(yard_said(&view, cx).starts_with("A password is wanted:"));
        assert!(!file.exists() && !session.exists());

        // Signing in keeps the session in a file of the yard's own, for
        // its user alone, and the road goes on to pairing the device.
        type_sign_in(
            &view,
            cx,
            "south",
            edge.address(),
            KRATOS_EMAIL,
            KRATOS_PASSWORD,
        );
        click_on(cx, "yard sign in");
        view.read_with(cx, |v, cx| {
            assert!(v.password.read(cx).text().is_empty());
        });
        wait(cx, "the sign-in", |cx| {
            yard_said(&view, cx).starts_with(&format!("Signed in as {KRATOS_EMAIL}: now pair"))
        });
        assert_eq!(
            view.read_with(cx, |v, _| v.adding.clone()),
            Some(Adding::Again("south".to_string()))
        );
        assert_eq!(open_yard(&view, cx), "south");
        let minted = yard::read_session(&session).unwrap();
        assert!(minted.starts_with("kratos-test-session-"), "{minted}");
        assert_eq!(mode_of(&session), 0o600);
        assert_eq!(
            yard::session_for(&session, &api::Address::parse(edge.address()).unwrap()).unwrap(),
            minted
        );
        // The password stands nowhere: not in a field, a file or a
        // setting. The session is in its file alone.
        view.read_with(cx, |v, cx| {
            assert_eq!(v.password.read(cx).text().to_string(), "");
            assert_eq!(v.email.read(cx).text().to_string(), "");
        });
        let kept = std::fs::read_to_string(&file).unwrap();
        assert!(kept.contains(&format!("\"account\": \"{KRATOS_EMAIL}\"")));
        for held in [&kept, &std::fs::read_to_string(&session).unwrap()] {
            assert!(!held.contains(KRATOS_PASSWORD), "{held}");
        }
        assert!(!kept.contains(&minted));
        let south = Settings::read(&file).yard("south").unwrap().clone();
        assert!(south.is_hosted());
        assert_eq!(south.account, KRATOS_EMAIL);

        // The code from the ready page pairs the device through the edge,
        // with the session beside it: the yard's conversations, with the
        // signed-in account under the yard's name.
        far.pair("K7QM-2XPD");
        view.update(cx, |v, cx| {
            v.code.update(cx, |line, cx| line.set_text("WXYZ-2345", cx));
        });
        click_on(cx, "yard pair");
        wait(cx, "that hosted pairing rejected the code", |cx| {
            yard_said(&view, cx).starts_with("Pairing failed: That is not the code.")
        });
        assert!(yard_said(&view, cx).contains("Check the code on the ready page"));
        assert!(far.pairing_open());
        assert!(!token.exists());

        view.update(cx, |v, cx| {
            v.code.update(cx, |line, cx| line.set_text("K7QM-2XPD", cx));
        });
        click_on(cx, "yard pair");
        wait(cx, "the yard at the origin", |cx| {
            texts(&view, cx) == ["From afar."]
        });
        assert_eq!(mode_of(&token), 0o600);
        assert_eq!(open_yard(&view, cx), "south");
        assert_eq!(
            which_yard(&view, cx),
            format!(
                "the yard south at {}, as its device laptop, signed in as {KRATOS_EMAIL}",
                edge.address()
            )
        );
    }

    /// A wrong password fails the sign-in and names it: the sign-in, never
    /// the pairing, with what to do. Nothing is kept, and the pairing
    /// stays open.
    #[gpui::test]
    fn a_wrong_password_says_the_sign_in_failed_and_pairs_nothing(cx: &mut TestAppContext) {
        use crate::fake::{KRATOS_EMAIL, Router};

        let dir = tempfile::tempdir().unwrap();
        let far = Yard::start_tcp();
        a_far_yard_of_jo(&far);
        let edge = Router::start(&far, "kratos-dev-other");
        let file = dir.path().join("footplate/settings.json");
        let (view, cx) = no_yard(dir.path(), cx);
        click_on(cx, "way hosted");

        far.pair("K7QM-2XPD");
        type_sign_in(
            &view,
            cx,
            "south",
            edge.address(),
            KRATOS_EMAIL,
            "not-the-password",
        );
        click_on(cx, "yard sign in");
        wait(cx, "that the sign-in failed", |cx| {
            yard_said(&view, cx).starts_with("The sign-in failed: ")
        });
        let said = yard_said(&view, cx);
        assert!(said.contains("provided credentials are invalid"), "{said}");
        assert!(
            said.ends_with("Check the email and password, and sign in again."),
            "{said}"
        );
        assert!(!said.contains("not-the-password"), "{said}");
        // Nothing changed: the fields stand with the email, the password
        // stands nowhere, and the pairing is still open.
        assert_eq!(
            view.read_with(cx, |v, _| v.adding.clone()),
            Some(Adding::Hosted)
        );
        view.read_with(cx, |v, cx| {
            assert_eq!(v.email.read(cx).text().to_string(), KRATOS_EMAIL);
            assert_eq!(v.password.read(cx).text().to_string(), "");
        });
        assert!(!file.exists());
        assert!(far.pairing_open());
        assert_eq!(far.devices(), [crate::fake::TOKEN]);
    }

    /// A hosted yard whose session the edge no longer knows is signed in
    /// again from where it says so: the session file is renewed, and the
    /// yard opens with the new one.
    #[gpui::test]
    fn signing_in_again_renews_the_session_and_reopens_the_yard(cx: &mut TestAppContext) {
        use crate::fake::{KRATOS_EMAIL, KRATOS_PASSWORD, Router, SESSION};

        let dir = tempfile::tempdir().unwrap();
        let near = Yard::start();
        a_yard_of_jo(&near);
        let far = Yard::start_tcp();
        a_far_yard_of_jo(&far);
        let edge = Router::start(&far, SESSION);
        let file = dir.path().join("footplate/settings.json");
        let session = dir.path().join("footplate/yard-south.session");
        let mut south = settings::Yard::hosted(
            "south",
            edge.address(),
            "yard-south.token",
            "yard-south.session",
        );
        south.account = KRATOS_EMAIL.to_string();
        Settings::default()
            .with_yard(None, south, Some(&file))
            .unwrap()
            .opening("south")
            .write(&file)
            .unwrap();
        yard::keep_token(
            &dir.path().join("footplate/yard-south.token"),
            crate::fake::TOKEN,
        )
        .unwrap();
        yard::keep_session_token(&session, SESSION).unwrap();
        let env = Env {
            socket: near.socket().to_path_buf(),
            ..Env::default()
        };
        let (view, cx) = opened_at(env, &file, cx);
        wait(cx, "the hosted yard's conversations", |cx| {
            texts(&view, cx) == ["From afar."]
        });
        assert_eq!(open_yard(&view, cx), "south");

        // The session is revoked at the edge: signing in again is
        // offered where the yard says so. (That pairing again is not is
        // the session-out test's: this yard passes through trying first,
        // whose frame the test still sees.)
        edge.revoke(SESSION);
        wait(cx, "that the session is not signed in", |cx| {
            view.read_with(cx, |v, _| v.away == Away::SignedOut)
        });
        // The away screen's own button stands clear of the ways, and its
        // centre signs this yard in again: not a way, and no settings
        // first.
        let (way, again) = (bounds_of(cx, "way far"), bounds_of(cx, "sign in again"));
        assert!(again.top() >= way.bottom(), "{again:?} {way:?}");
        click_on(cx, "sign in again");
        assert!(settings_open(&view, cx));
        assert_eq!(
            view.read_with(cx, |v, _| v.adding.clone()),
            Some(Adding::SignInAgain("south".to_string()))
        );
        assert!(drawn(cx, "yard sign in for") && drawn(cx, "yard sign in"));
        // The email stands filled with the yard's account; the password is
        // typed.
        assert_eq!(
            view.read_with(cx, |v, cx| v.email.read(cx).text().to_string()),
            KRATOS_EMAIL
        );
        view.update(cx, |v, cx| {
            v.password
                .update(cx, |line, cx| line.set_text(KRATOS_PASSWORD, cx));
        });
        click_on(cx, "yard sign in");
        wait(cx, "the yard again", |cx| {
            texts(&view, cx) == ["From afar."] && view.read_with(cx, |v, _| v.down.is_none())
        });
        assert!(yard_said(&view, cx).starts_with(&format!("Signed in as {KRATOS_EMAIL}.")));
        let renewed = yard::read_session(&session).unwrap();
        assert_ne!(renewed, SESSION);
        assert!(renewed.starts_with("kratos-test-session-"), "{renewed}");
        assert_eq!(mode_of(&session), 0o600);
    }

    /// A yard that answered and goes away keeps its view: the list, the
    /// decisions and the open conversation stay as last seen, the status
    /// row is the one quiet line, and Send is held with
    /// the reason beside the line: the draft stays as typed, and goes
    /// on Enter once the yard answers. Nothing is queued meanwhile.
    #[gpui::test]
    fn a_yard_that_answered_and_goes_away_keeps_its_view_and_holds_send(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        let socket = yard.socket().to_path_buf();
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        cx.simulate_input("Land it when green.");
        yard.stop();
        wait(cx, "that the yard is away", |cx| {
            view.read_with(cx, |v, _| v.down.is_some())
        });
        wait(cx, "the switch read after the yard went away", |cx| {
            settled(&view, cx)
        });
        // A failed switch read must not hide the follower's reconnecting
        // state in the head.
        let (program, note) =
            view.read_with(cx, |v, _| (v.switch_program.clone(), v.switch_note.clone()));
        view.update(cx, |v, cx| {
            v.switch_program = None;
            v.switch_note = Some("yardr could not be fetched".to_string());
            cx.notify();
        });
        assert!(drawn(cx, "reconnecting"));
        view.update(cx, |v, cx| {
            v.switch_program = program;
            v.switch_note = note;
            cx.notify();
        });
        // As last seen: the rows, the conversation, and the quiet line.
        // (The away screen painted before the first answer, so its
        // absence is the state, not the selectors.)
        assert!(view.read_with(cx, |v, _| v.reconnecting()));
        assert_eq!(texts(&view, cx), ["Shall I land it?"]);
        assert!(drawn(cx, "rows") && drawn(cx, "conversation top"));
        assert!(drawn(cx, "reconnecting") && drawn(cx, "send held"));
        // Send is held: the draft stays, and nothing goes.
        assert_eq!(typed(&view, cx), "Land it when green.");
        cx.simulate_keystrokes("enter");
        cx.run_until_parked();
        assert_eq!(typed(&view, cx), "Land it when green.");
        assert_eq!(yard.asked("Mail"), Vec::<Value>::new());
        // It is back: the hold is gone with the state, everything is
        // read again, and the draft goes on Enter.
        let yard = Yard::start_at(&socket);
        a_yard_of_jo(&yard);
        wait(cx, "the yard again", |cx| {
            view.read_with(cx, |v, _| v.down.is_none())
        });
        assert!(view.read_with(cx, |v, _| !v.reconnecting()));
        assert_eq!(texts(&view, cx), ["Shall I land it?"]);
        assert_eq!(typed(&view, cx), "Land it when green.");
        cx.simulate_keystrokes("enter");
        wait(cx, "the draft to be sent", |_| {
            yard.asked("Mail")
                == [json!({"to": "yardmaster", "text": "Land it when green.", "actor": "jo"})]
        });
        assert_eq!(typed(&view, cx), "");
    }

    /// A yard whose arrivals board is garbage still comes back: after a
    /// stream end the state is read, the board stands empty with why as
    /// the notice, and the rest is drawn as usual.
    #[gpui::test]
    fn a_yard_whose_arrivals_are_garbage_comes_back_with_a_notice(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        let socket = yard.socket().to_path_buf();
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        yard.stop();
        wait(cx, "that the yard is away", |cx| {
            view.read_with(cx, |v, _| v.down.is_some())
        });
        // It is back, but its board is garbage: the window comes back
        // with the rest drawn and a notice saying why the board stands
        // empty.
        let yard = Yard::start_at(&socket);
        a_yard_of_jo(&yard);
        yard.answer("Arrivals", r#"{"result": [7]}"#);
        wait(cx, "the yard again", |cx| {
            view.read_with(cx, |v, _| v.down.is_none())
        });
        assert!(view.read_with(cx, |v, _| !v.reconnecting()));
        assert_eq!(texts(&view, cx), ["Shall I land it?"]);
        assert!(drawn(cx, "rows") && drawn(cx, "conversation top"));
        assert!(
            notice(&view, cx).starts_with("the arrivals could not be read: "),
            "{}",
            notice(&view, cx)
        );
        view.read_with(cx, |v, _| {
            assert!(v.model.as_ref().unwrap().arrival_rows().is_empty());
        });
    }

    /// Answers on a decision card are held as a conversation's sends are:
    /// the words stay where they are typed, the Send button stands
    /// disabled with the reason beside it, and Enter holds them too.
    #[gpui::test]
    fn answers_on_a_decision_card_are_held_while_the_yard_is_away(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("UserAsks", &asks_words_only());
        yard.answer("Bead", &bead_words_only());
        yard.answer("AnswerAsk", "{}");
        cx.update(|cx| {
            input::bind_keys(cx);
            bind_keys(cx);
        });
        let (view, cx) = cx.add_window_view(|window, cx| {
            let view = Footplate::new(yard.client(), "jo".into(), window, cx);
            window.focus(&view.line.focus_handle(cx));
            view
        });
        wait(cx, "the decision", |cx| {
            to_decisions(&view, cx);
            view.read_with(cx, |v, _| {
                v.model
                    .as_ref()
                    .is_some_and(|m| m.selected() == Some(&Selected::Decision("bead-w".into())))
            })
        });
        wait(cx, "the bead", |cx| has_bead(&view, cx, "bead-w"));
        let socket = yard.socket().to_path_buf();
        yard.stop();
        wait(cx, "that the yard is away", |cx| {
            view.read_with(cx, |v, _| v.down.is_some())
        });
        assert!(view.read_with(cx, |v, _| v.reconnecting()));
        assert!(drawn(cx, "send bead-w 9") && drawn(cx, "send held"));
        // The words are typed while the yard is away, and held: from
        // Enter as from the button, nothing goes. The mode step left the
        // focus on the window, as opening a card does, so `i` types in
        // the card's line first.
        cx.simulate_keystrokes("i");
        cx.simulate_input("warmly");
        assert_eq!(typed(&view, cx), "warmly");
        cx.simulate_keystrokes("enter");
        cx.run_until_parked();
        assert_eq!(typed(&view, cx), "warmly");
        click_on(cx, "send bead-w 9");
        cx.run_until_parked();
        assert_eq!(typed(&view, cx), "warmly");
        assert_eq!(yard.asked("AnswerAsk"), Vec::<Value>::new());
        // It is back: the words go on Enter.
        let yard = Yard::start_at(&socket);
        a_yard_of_jo(&yard);
        yard.answer("UserAsks", &asks_words_only());
        yard.answer("Bead", &bead_words_only());
        yard.answer("AnswerAsk", "{}");
        wait(cx, "the yard again", |cx| {
            view.read_with(cx, |v, _| v.down.is_none())
        });
        cx.simulate_keystrokes("enter");
        wait(cx, "the answer", |_| {
            yard.asked("AnswerAsk")
                == [
                    json!({"bead": "bead-w", "ask": 9, "option": 0, "words": "warmly", "actor": "jo"}),
                ]
        });
        assert_eq!(typed(&view, cx), "");
    }

    /// A yard at an address has no status row: while it is reconnecting
    /// the quiet line is the strip at the top of the conversation, and
    /// Send is held as on a yard of this machine.
    #[gpui::test]
    fn a_far_yard_that_goes_away_says_so_in_a_strip_and_holds_send(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let far = Yard::start_tcp();
        a_far_yard_of_jo(&far);
        let file = dir.path().join("footplate/settings.json");
        Settings {
            yards: vec![settings::Yard::far("far", far.address(), "yard-far.token")],
            open: "far".to_string(),
            ..Settings::default()
        }
        .write(&file)
        .unwrap();
        yard::keep_token(
            &dir.path().join("footplate/yard-far.token"),
            crate::fake::TOKEN,
        )
        .unwrap();
        let env = Env {
            socket: dir.path().join("yard.sock"),
            ..Env::default()
        };
        let (view, cx) = opened_at(env, &file, cx);
        wait(cx, "the yard's conversation", |cx| {
            texts(&view, cx) == ["From afar."]
        });
        cx.simulate_input("Noted.");
        far.stop();
        wait(cx, "that the yard is away", |cx| {
            view.read_with(cx, |v, _| v.down.is_some())
        });
        assert!(view.read_with(cx, |v, _| v.reconnecting()));
        assert_eq!(texts(&view, cx), ["From afar."]);
        assert!(drawn(cx, "reconnecting") && drawn(cx, "send held"));
        assert!(!drawn(cx, "away why") && !drawn(cx, "switch state"));
        cx.simulate_keystrokes("enter");
        cx.run_until_parked();
        assert_eq!(typed(&view, cx), "Noted.");
        assert_eq!(far.asked("Mail"), Vec::<Value>::new());
    }

    /// A far yard has no status row: even with Settings open instead
    /// of its conversation, its reconnecting strip stays visible.
    #[gpui::test]
    fn a_far_yard_reconnecting_in_settings_says_so(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let far = Yard::start_tcp();
        a_far_yard_of_jo(&far);
        let file = dir.path().join("footplate/settings.json");
        Settings {
            yards: vec![settings::Yard::far("far", far.address(), "yard-far.token")],
            open: "far".to_string(),
            ..Settings::default()
        }
        .write(&file)
        .unwrap();
        yard::keep_token(
            &dir.path().join("footplate/yard-far.token"),
            crate::fake::TOKEN,
        )
        .unwrap();
        let env = Env {
            socket: dir.path().join("yard.sock"),
            ..Env::default()
        };
        let (view, cx) = opened_at(env, &file, cx);
        wait(cx, "the far yard's conversation", |cx| {
            texts(&view, cx) == ["From afar."]
        });
        click_on(cx, "settings");
        wait(cx, "settings to open", |cx| {
            view.read_with(cx, |v, _| v.settings_open)
        });
        assert!(!drawn(cx, "reconnecting"));
        far.stop();
        wait(cx, "the far yard to reconnect", |cx| {
            view.read_with(cx, |v, _| v.reconnecting())
        });
        assert!(drawn(cx, "reconnecting"));
    }

    /// The one yard the environment names has no other to go to: away, it
    /// keeps the rail with the gear and no tile, its modes dimmed and
    /// inert.
    #[gpui::test]
    fn the_environment_s_yard_away_has_no_switcher(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let token = dir.path().join("mac.token");
        yard::keep_token(&token, crate::fake::TOKEN).unwrap();
        let far = Yard::start_tcp();
        far.stop();
        let env = Env {
            yard: Some(far.address().to_string()),
            token_file: Some(token),
            socket: dir.path().join("yard.sock"),
        };
        let (view, cx) = opened_at(env, &file, cx);
        wait(cx, "that nothing answers", |cx| {
            view.read_with(cx, |v, _| {
                v.down
                    .as_deref()
                    .is_some_and(|why| why.starts_with("No yard: nothing answers"))
            })
        });
        assert!(drawn(cx, "away why") && drawn(cx, "settings"));
        assert!(!drawn(cx, "switch tile"));
        // Nor a way to another yard: it is the one there is.
        assert!(!drawn(cx, "way near") && !drawn(cx, "way far") && !drawn(cx, "way hosted"));
        assert!(!drawn(cx, "way here"));
        cx.simulate_keystrokes("secondary-y");
        assert_eq!(switching(&view, cx), None);
        // The rail stands with the mark and the three modes, dimmed and
        // inert: a click and the brackets change nothing.
        assert!(drawn(cx, "rail mark"));
        assert!(drawn(cx, "rail chat") && drawn(cx, "rail decisions"));
        assert!(drawn(cx, "rail timetable"));
        click_on(cx, "rail timetable");
        cx.simulate_keystrokes("secondary-]");
        cx.run_until_parked();
        assert_eq!(rail_mode(&view, cx), Mode::Chat);
        assert!(view.read_with(cx, |v, _| v.model.is_none()));
        // The gear stays alive: the settings open from the rail.
        click_on(cx, "settings");
        assert!(settings_open(&view, cx));
    }

    /// A window with nothing at this run's socket and no settings kept:
    /// the first screen, once it says there is no yard.
    fn no_yard<'a>(
        dir: &std::path::Path,
        cx: &'a mut TestAppContext,
    ) -> (Entity<Footplate>, &'a mut VisualTestContext) {
        let env = Env {
            socket: dir.join("yard.sock"),
            ..Env::default()
        };
        let (view, cx) = opened_at(env, &dir.join("footplate/settings.json"), cx);
        wait(cx, "that there is no yard", |cx| {
            view.read_with(cx, |v, _| {
                v.down
                    .as_deref()
                    .is_some_and(|why| why.starts_with("No yard: nothing answers"))
            })
        });
        (view, cx)
    }

    /// With no yard the window offers the ways to one, which are the
    /// settings' entries: a yard of this machine by its socket, where this
    /// run's stands to begin with, is added and opened from there, with no
    /// settings shown. Esc leaves the fields.
    #[gpui::test]
    fn no_yard_offers_a_yard_of_this_machine_by_its_socket(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let second = Yard::start();
        a_second_yard_of_jo(&second);
        let (view, cx) = no_yard(dir.path(), cx);
        assert_eq!(view.read_with(cx, |v, _| v.away), Away::Trying);
        assert!(drawn(cx, "away why"));
        // The ways, and nothing asked until one is taken.
        assert!(drawn(cx, "way near") && drawn(cx, "way far") && drawn(cx, "way hosted"));
        assert!(!drawn(cx, "yard name") && !drawn(cx, "yard pair"));
        let adding = |view: &Entity<Footplate>, cx: &mut VisualTestContext| {
            view.read_with(cx, |v, _| v.adding.clone())
        };

        click_on(cx, "way near");
        assert_eq!(adding(&view, cx), Some(Adding::Near));
        assert!(drawn(cx, "yard name") && drawn(cx, "yard socket") && drawn(cx, "yard pair"));
        // The fields have room for a path, under the buttons and inside
        // the window.
        let (field, way) = (bounds_of(cx, "yard socket"), bounds_of(cx, "way near"));
        assert!(field.size.width > px(200.), "{field:?}");
        assert!(field.top() > way.bottom(), "{field:?} {way:?}");
        let window = cx.update(|window, _| window.viewport_size());
        assert!(field.right() < window.width && field.bottom() < window.height);
        // This run's socket stands in the field, and the name is typed:
        // every letter of it, with no card whose keys `e` and `d` are.
        assert_eq!(
            view.read_with(cx, |v, cx| v.socket.read(cx).text().to_string()),
            dir.path().join("yard.sock").to_str().unwrap()
        );
        cx.simulate_input("second home");
        assert_eq!(
            view.read_with(cx, |v, cx| v.yard_name.read(cx).text().to_string()),
            "second home"
        );
        // Esc leaves the fields, and the window is as it was.
        cx.simulate_keystrokes("escape");
        assert_eq!(adding(&view, cx), None);
        assert!(!settings_open(&view, cx));
        assert!(view.read_with(cx, |v, _| v.down.is_some()));

        // No name: said, and nothing changed.
        click_on(cx, "way near");
        cx.simulate_keystrokes("enter");
        assert!(
            yard_said(&view, cx).starts_with("A yard wants a name"),
            "{}",
            yard_said(&view, cx)
        );
        assert!(!file.exists());
        // The second home's socket in place of this run's, and Enter.
        view.update(cx, |v, cx| {
            v.yard_name
                .update(cx, |line, cx| line.set_text("second home", cx));
            let socket = second.socket().to_str().unwrap().to_string();
            v.socket.update(cx, |line, cx| line.set_text(&socket, cx));
        });
        cx.simulate_keystrokes("enter");
        wait(cx, "the second home's yard", |cx| {
            texts(&view, cx) == ["From the second home."]
        });
        assert_eq!(view.read_with(cx, |v, _| v.down.clone()), None);
        assert_eq!(adding(&view, cx), None);
        assert!(!settings_open(&view, cx));
        assert_eq!(open_yard(&view, cx), "second home");
        // It is kept, after this machine's, and is the one to open next.
        let kept = Settings::read(&file);
        assert_eq!(
            kept.yards[1],
            settings::Yard::near("second home", second.socket().to_str().unwrap())
        );
        assert_eq!(kept.open, "second home");
        // The line has the keys, as after a switch.
        cx.simulate_input("hello");
        assert_eq!(typed(&view, cx), "hello");
    }

    /// What the first run of a test reaches out with: a stand-in for
    /// yardr in `dir`, which is not fetched from anywhere, a home under
    /// `dir`, and a list in place of the browser. The stand-in's path, and
    /// the pages that were opened.
    fn stand_in_means(
        dir: &std::path::Path,
        apple: bool,
    ) -> (Means, PathBuf, Rc<RefCell<Vec<String>>>) {
        let program = crate::setup::standin::make(&dir.join("fetched"));
        let home = dir.join("home");
        std::fs::create_dir_all(&home).unwrap();
        let opened: Rc<RefCell<Vec<String>>> = Rc::default();
        let (fetched, pages) = (program.clone(), opened.clone());
        let means = Means {
            yardr: Arc::new(move || Ok((fetched.clone(), None))),
            path: "/usr/bin:/bin".into(),
            home: Some(home),
            own: Some(dir.join("own")),
            open: Rc::new(move |url, _| pages.borrow_mut().push(url.to_string())),
            apple,
        };
        (means, program, opened)
    }

    fn step_of(view: &Entity<Footplate>, cx: &mut VisualTestContext) -> Option<firstrun::Step> {
        view.read_with(cx, |v, cx| v.first_run.as_ref().map(|f| f.read(cx).step))
    }

    fn setup_said(view: &Entity<Footplate>, cx: &mut VisualTestContext) -> String {
        view.read_with(cx, |v, cx| {
            let said = v.first_run.as_ref().and_then(|f| f.read(cx).said.clone());
            said.unwrap_or_default()
        })
    }

    /// Waits until the first run stands at `step` with nothing underway.
    fn at_step(view: &Entity<Footplate>, cx: &mut VisualTestContext, step: firstrun::Step) {
        wait(cx, &format!("the first run at {step:?}"), |cx| {
            view.read_with(cx, |v, cx| {
                v.first_run.as_ref().is_some_and(|f| {
                    let f = f.read(cx);
                    f.step == step && f.busy.is_none()
                })
            })
        });
    }

    fn type_setup(view: &Entity<Footplate>, cx: &mut VisualTestContext, field: &str, text: &str) {
        view.update(cx, |v, cx| {
            let first_run = v.first_run.clone().unwrap();
            first_run.update(cx, |f, cx| f.type_in(field, text, cx));
        });
    }

    fn setup_typed(view: &Entity<Footplate>, cx: &mut VisualTestContext, field: &str) -> String {
        view.read_with(cx, |v, cx| {
            v.first_run.as_ref().unwrap().read(cx).typed_in(field, cx)
        })
    }

    /// The first run's provider buttons: each installed harness's kind
    /// with its button's text.
    fn setup_providers(
        view: &Entity<Footplate>,
        cx: &mut VisualTestContext,
    ) -> Vec<(String, String)> {
        view.read_with(cx, |v, cx| {
            v.first_run.as_ref().unwrap().read(cx).provider_buttons()
        })
    }

    /// The first run's model pick: each button's picked id (None is the
    /// harness's own choice) with its text.
    fn setup_models(
        view: &Entity<Footplate>,
        cx: &mut VisualTestContext,
    ) -> Vec<(Option<String>, String)> {
        view.read_with(cx, |v, cx| {
            v.first_run.as_ref().unwrap().read(cx).model_buttons()
        })
    }

    /// The first run's picked model id: None is the harness's own choice.
    fn setup_picked(view: &Entity<Footplate>, cx: &mut VisualTestContext) -> Option<String> {
        view.read_with(cx, |v, cx| {
            v.first_run.as_ref().unwrap().read(cx).picked_model()
        })
    }

    /// The first run at its second step, with the stand-in answering
    /// `doctor`: the window with no yard, "way here", and "go on" once
    /// the machine is ready. The stand-in's path, for its answers and
    /// its calls.
    fn at_yard<'a>(
        dir: &tempfile::TempDir,
        doctor: &serde_json::Value,
        cx: &'a mut TestAppContext,
    ) -> (Entity<Footplate>, &'a mut VisualTestContext, PathBuf) {
        use crate::setup::standin;
        use firstrun::Step;

        let (means, program, _) = stand_in_means(dir.path(), true);
        standin::answers(&program, "doctor", 0, doctor);
        let (view, cx) = no_yard(dir.path(), cx);
        view.update(cx, |v, _| v.means = means);
        click_on(cx, "way here");
        at_step(&view, cx, Step::Needs);
        click_on(cx, "setup go on");
        assert_eq!(step_of(&view, cx), Some(Step::Yard));
        (view, cx, program)
    }

    /// A fetch is a Mac road from yardr's data. Even if a doctor answer
    /// includes one on Linux, the row stays a list with the vendor's page.
    #[gpui::test]
    fn linux_keeps_a_doctor_fetch_as_a_page_and_never_offers_install(cx: &mut TestAppContext) {
        use crate::setup::standin;
        use firstrun::Step;

        let dir = tempfile::tempdir().unwrap();
        let (means, program, _) = stand_in_means(dir.path(), false);
        let home = dir.path().join("home");
        standin::answers(&program, "doctor", 1, &standin::doctor_bare(&home));
        let (view, cx) = no_yard(dir.path(), cx);
        view.update(cx, |v, _| v.means = means);

        click_on(cx, "way here");
        at_step(&view, cx, Step::Needs);

        assert!(!drawn(cx, "setup install herdr"));
        assert!(drawn(cx, "setup page herdr"));
        assert!(drawn(cx, "setup get herdr"));
        assert!(!home.join(".local/bin/herdr").exists());
    }

    /// The third way, from no yard to talking with the yardmaster: yardr
    /// is had, what the machine lacks is listed from doctor's JSON with
    /// how each comes, the yard is created without being started, the
    /// harness's login is led by what yardr asks for, the yard is started,
    /// a folder becomes its depot with a first bead, and the yardmaster's
    /// conversation is open. Every step is a command of the stand-in for
    /// yardr, with a PATH made from doctor's data.
    #[gpui::test]
    fn no_yard_offers_to_set_one_up_here_and_ends_talking_with_the_yardmaster(
        cx: &mut TestAppContext,
    ) {
        use crate::setup::standin;
        use firstrun::Step;

        let dir = tempfile::tempdir().unwrap();
        let (means, program, opened) = stand_in_means(dir.path(), true);
        let home = dir.path().join("home");
        standin::answers(&program, "doctor", 1, &standin::doctor_bare(&home));
        let (view, cx) = no_yard(dir.path(), cx);
        view.update(cx, |v, _| v.means = means);
        assert!(
            drawn(cx, "way here")
                && drawn(cx, "way near")
                && drawn(cx, "way far")
                && drawn(cx, "way hosted")
        );
        assert!(!drawn(cx, "setup step"));

        // What this needs: doctor's rows, each with how it comes.
        click_on(cx, "way here");
        at_step(&view, cx, Step::Needs);
        assert!(drawn(cx, "setup step"));
        for row in ["git", "herdr", "claude", "opencode"] {
            assert!(drawn(cx, &format!("setup row {row}")), "{row}");
        }
        // herdr has a way yardr names; the harnesses here have a page, and
        // yardr's words for installing them by hand.
        assert!(drawn(cx, "setup install herdr") && !drawn(cx, "setup install claude"));
        assert!(drawn(cx, "setup get claude") && !drawn(cx, "setup get herdr"));
        assert!(!drawn(cx, "setup install git") && !drawn(cx, "setup page git"));
        click_on(cx, "setup page claude");
        assert_eq!(*opened.borrow(), ["https://claude.com/claude-code"]);
        // Nothing goes on while herdr and a harness are missing.
        click_on(cx, "setup go on");
        assert_eq!(step_of(&view, cx), Some(Step::Needs));
        // What is started finds what doctor found: the login shell's
        // directory and the one a program is fetched to.
        let wide = format!(
            "/usr/bin:/bin:{}:/opt/stand-in/bin",
            home.join(".local/bin").display()
        );
        let path = view.read_with(cx, |v, cx| v.first_run.as_ref().unwrap().read(cx).path());
        assert_eq!(path, Some(wide.clone().into()));

        // They are installed: checked again, a herdr whose server is down
        // waits and keeps nothing back.
        standin::answers(&program, "doctor", 0, &standin::doctor_ready());
        click_on(cx, "setup check");
        wait(cx, "herdr's server waiting", |cx| {
            drawn(cx, "setup server waits")
        });
        click_on(cx, "setup go on");
        assert_eq!(step_of(&view, cx), Some(Step::Yard));

        // Your yard: the login name stands in the field, the first
        // provider is chosen, and one with no login recipe says so.
        assert_eq!(setup_typed(&view, cx, "your name"), "jo");
        assert!(drawn(cx, "setup provider claude") && drawn(cx, "setup provider codex"));
        assert!(drawn(cx, "setup style guide") && drawn(cx, "setup style report"));
        // The row is the scale it is: the question, the four numbered in
        // order, and the line that they change later.
        assert!(drawn(cx, "setup savvy") && drawn(cx, "setup change later"));
        let left = |key: &str| bounds_of(cx, &format!("setup style {key}")).origin.x;
        let places: Vec<_> = ["guide", "show", "work", "report"]
            .into_iter()
            .map(left)
            .collect();
        assert!(places.windows(2).all(|pair| pair[0] < pair[1]));
        // The name is typed where the focus is: every letter of it.
        cx.simulate_keystrokes("secondary-a");
        cx.simulate_input("Jo Deed");
        assert_eq!(setup_typed(&view, cx, "your name"), "Jo Deed");
        type_setup(&view, cx, "about you", "I teach history");
        standin::answers(&program, "init", 0, &json!({"harness": "claude"}));
        cx.simulate_keystrokes("enter");
        at_step(&view, cx, Step::Login);
        let calls = standin::calls(&program);
        let yard = dir.path().display();
        assert_eq!(
            calls.last().unwrap(),
            &format!(
                "[init] [--harness=claude] [--operator=Jo Deed] [--yardmaster=yardmaster] [--style=guide] [--about=I teach history] [--json] [--home] [{yard}] [--actor=Jo Deed]"
            )
        );

        // The login: the ways yardr names as buttons, the page as a
        // button, the code in a field that keeps nothing, and the
        // question before the one real call.
        click_on(cx, "setup log in");
        wait(cx, "the ways to log in", |cx| drawn(cx, "setup method 1"));
        click_on(cx, "setup method 0");
        wait(cx, "the page and the code's field", |cx| {
            drawn(cx, "setup page") && drawn(cx, "setup code")
        });
        click_on(cx, "setup page");
        assert_eq!(
            opened.borrow()[1],
            "https://claude.com/cai/oauth/authorize?code=true"
        );
        // The field has the keys, and shows none of what is typed.
        cx.simulate_input("good#code");
        assert_eq!(setup_typed(&view, cx, "code"), "good#code");
        cx.simulate_keystrokes("enter");
        assert_eq!(setup_typed(&view, cx, "code"), "");
        wait(cx, "the question before the real call", |cx| {
            drawn(cx, "setup prove")
        });
        click_on(cx, "setup prove");
        at_step(&view, cx, Step::Start);
        assert_eq!(setup_said(&view, cx), "Logged in, and the harness answers.");
        assert_eq!(
            standin::answered(&program),
            [
                r#"{"choose":"Claude subscription"}"#,
                r#"{"input":"good#code"}"#,
                r#"{"confirm":true}"#
            ]
        );

        // Start: what yardr could not start is said in its words, and the
        // yard that then runs is followed by itself, under the first run.
        standin::answers(
            &program,
            "up.1",
            1,
            &json!({"up": false, "parts": [
                {"part": "herdr", "running": false, "error": "its server did not come up.", "do": "Look at herdr-server.log."}]}),
        );
        standin::answers(&program, "up", 0, &json!({"up": true, "parts": []}));
        click_on(cx, "setup start");
        wait(cx, "what could not be started", |cx| {
            setup_said(&view, cx) == "herdr: its server did not come up. Look at herdr-server.log."
        });
        assert_eq!(step_of(&view, cx), Some(Step::Start));
        let near = Yard::start_at(&dir.path().join("yard.sock"));
        a_yard_of_jo(&near);
        click_on(cx, "setup start");
        at_step(&view, cx, Step::Depot);
        wait(cx, "the yard that was started", |cx| {
            view.read_with(cx, |v, _| v.down.is_none() && v.model.is_some())
        });
        assert!(view.read_with(cx, |v, _| v.first_run.is_some()));

        // The folder: its name is offered, and a folder that is no git
        // checkout has no branch. The import's questions are answered.
        let folder = dir.path().join("My Essays");
        std::fs::create_dir(&folder).unwrap();
        view.update(cx, |v, cx| {
            let first_run = v.first_run.clone().unwrap();
            first_run.update(cx, |f, cx| f.chose(&folder, cx));
        });
        assert_eq!(setup_typed(&view, cx, "name"), "my-essays");
        assert_eq!(setup_typed(&view, cx, "base branch"), "");
        standin::answers(
            &program,
            "depot-add",
            0,
            &json!({"name": "my-essays", "kind": "dir"}),
        );
        standin::answers(
            &program,
            "depot-init.1",
            2,
            &json!({"error": "depot init cannot ask without a terminal",
                    "missing": ["--bind builders=<kind>[:<model>]", "--members decisions=<users>"]}),
        );
        standin::answers(
            &program,
            "depot-init",
            0,
            &json!({"result": {"created": 9}}),
        );
        click_on(cx, "setup set up");
        at_step(&view, cx, Step::Bead);

        // The first bead, and the yardmaster's conversation.
        type_setup(&view, cx, "title", "A first draft");
        type_setup(&view, cx, "done when", "It reads well aloud.");
        standin::answers(&program, "bead-create", 0, &json!({"id": "my-essays-1a2b"}));
        standin::answers(
            &program,
            "bead-advance",
            0,
            &json!({"id": "my-essays-1a2b"}),
        );
        standin::answers(&program, "subscribe", 0, &json!([]));
        click_on(cx, "setup hand on");
        wait(cx, "the yardmaster's conversation", |cx| {
            open_row(&view, cx) == Some(Selected::Conversation("yardmaster".into()))
        });
        assert!(view.read_with(cx, |v, _| v.first_run.is_none()));
        let tail = format!("[--json] [--home] [{yard}] [--actor=Jo Deed]");
        let calls = standin::calls(&program);
        let after_init: Vec<&str> = calls
            .iter()
            .skip_while(|call| !call.starts_with("[harness]"))
            .map(String::as_str)
            .collect();
        assert_eq!(
            after_init,
            [
                format!("[harness] [login] {tail} [--] [claude]"),
                format!("[up] {tail}"),
                format!("[up] {tail}"),
                format!(
                    "[depot] [add] {tail} [--] [my-essays] [{}]",
                    folder.display()
                ),
                format!("[depot] [init] [--yes] {tail} [--] [my-essays]"),
                format!(
                    "[depot] [init] [--yes] [--bind] [builders=claude] [--members] [decisions=Jo Deed] {tail} [--] [my-essays]"
                ),
                format!(
                    "[bead] [create] [--depot=my-essays] [-b] [It reads well aloud.] {tail} [--] [A first draft]"
                ),
                format!("[bead] [advance] [--to=new] {tail} [--] [my-essays-1a2b]"),
                format!(
                    "[subscribe] [--done] [--where=depot=my-essays] {tail} [--] [Jo Deed] [yardr]"
                ),
                // The first run over, the switch reads what it made:
                // doctor widening its PATH, then status. This run's yard
                // takes no home flag.
                "[doctor] [--json]".to_string(),
                "[status] [--json]".to_string(),
            ]
        );
        // Every one of the first run's with the PATH doctor's data made;
        // the switch's two read with its own, unwidened here.
        let paths = standin::paths(&program);
        assert!(
            paths[1..paths.len() - 2].iter().all(|path| *path == wide),
            "{paths:?}"
        );
        assert_eq!(
            &paths[paths.len() - 2..],
            ["/usr/bin:/bin", "/usr/bin:/bin"]
        );
        // The line has the keys, in the yardmaster's conversation.
        cx.simulate_input("hello");
        assert_eq!(typed(&view, cx), "hello");
    }

    /// The second step names the providers and picks the yardmaster's
    /// model from the chosen one's offers: the recommended one stands
    /// picked, and creating the yard sends its id.
    #[gpui::test]
    fn the_second_step_picks_the_yardmaster_s_model_from_the_provider_s_offers(
        cx: &mut TestAppContext,
    ) {
        use crate::setup::standin;
        use firstrun::Step;

        let dir = tempfile::tempdir().unwrap();
        let (view, cx, program) = at_yard(&dir, &standin::doctor_ready_with_offers(), cx);

        // The providers by their labels, the one with no login recipe
        // saying it needs a terminal once.
        assert!(drawn(cx, "setup provider claude") && drawn(cx, "setup provider codex"));
        assert_eq!(
            setup_providers(&view, cx),
            [
                ("claude".to_string(), "Anthropic · Claude Code".to_string()),
                (
                    "codex".to_string(),
                    "OpenAI · Codex (needs a terminal once to log in)".to_string()
                ),
            ]
        );
        // The model pick: the recommended offer stands picked and marked,
        // beside the harness's own choice.
        assert!(
            drawn(cx, "setup model opus")
                && drawn(cx, "setup model fable")
                && drawn(cx, "setup model sonnet")
                && drawn(cx, "setup model own")
        );
        assert_eq!(
            setup_models(&view, cx),
            [
                (
                    Some("opus".to_string()),
                    "Opus 5.5 (recommended)".to_string()
                ),
                (Some("fable".to_string()), "Fable 5.1".to_string()),
                (Some("sonnet".to_string()), "Sonnet 5".to_string()),
                (None, "the harness's own choice".to_string()),
            ]
        );
        assert_eq!(setup_picked(&view, cx), Some("opus".to_string()));

        // Creating the yard sends the picked id.
        standin::answers(&program, "init", 0, &json!({"harness": "claude"}));
        click_on(cx, "setup create");
        at_step(&view, cx, Step::Login);
        let yard = dir.path().display().to_string();
        assert_eq!(
            standin::calls(&program).last().unwrap(),
            &format!(
                "[init] [--harness=claude] [--operator=jo] [--yardmaster=yardmaster] [--style=guide] [--model=opus] [--json] [--home] [{yard}] [--actor=jo]"
            )
        );
    }

