    /// A home that has a yard already, which does not run: the first run
    /// creates nothing over it and asks nothing of it again. It starts the
    /// yard and opens its yardmaster's conversation, by the name the yard
    /// has for it.
    #[gpui::test]
    fn a_yard_that_is_there_and_stopped_is_started_and_not_created_again(cx: &mut TestAppContext) {
        use crate::setup::standin;
        use firstrun::Step;

        let dir = tempfile::tempdir().unwrap();
        let (means, program, _) = stand_in_means(dir.path(), true);
        let mut doctor = standin::doctor_ready();
        doctor["yard"] = json!(true);
        standin::answers(&program, "doctor", 0, &doctor);
        doctor["state"] = json!({"server": "running", "yardmaster": {"name": "assembly"}});
        standin::answers(&program, "up", 0, &json!({"up": true, "parts": []}));
        let (view, cx) = no_yard(dir.path(), cx);
        view.update(cx, |v, _| v.means = means);
        click_on(cx, "way here");
        at_step(&view, cx, Step::Needs);
        click_on(cx, "setup go on");
        assert_eq!(step_of(&view, cx), Some(Step::Start));
        assert!(setup_said(&view, cx).starts_with("This machine has a yard already"));

        let near = Yard::start_at(&dir.path().join("yard.sock"));
        a_yard_of_jo(&near);
        standin::answers(&program, "doctor", 0, &doctor);
        click_on(cx, "setup start");
        wait(cx, "the conversation of the yard's own yardmaster", |cx| {
            open_row(&view, cx) == Some(Selected::Conversation("assembly".into()))
        });
        assert!(view.read_with(cx, |v, _| v.first_run.is_none()));
        let calls = standin::calls(&program);
        let commands: Vec<&str> = calls
            .iter()
            .map(|call| call.split(' ').next().unwrap())
            .collect();
        assert_eq!(&commands[..3], ["[doctor]", "[up]", "[doctor]"]);
        // The first run over, the switch reads what it made: doctor for
        // the PATH, then status. Where the yard answers after that, a
        // second status follows; the follower's retry and the first run's
        // end race, so either tail stands.
        let tail = &commands[3..];
        assert!(
            tail == ["[doctor]", "[status]"] || tail == ["[doctor]", "[status]", "[status]"],
            "{commands:?}"
        );
        // Nobody said a name: the commands act as the login does.
        assert!(
            calls.iter().all(|call| !call.contains("--actor")),
            "{calls:?}"
        );
    }

    /// The switch is at rest: nothing of it runs, and no reading is
    /// underway. Tests wait for this between its acts, so each reads in
    /// turn.
    fn settled(view: &Entity<Footplate>, cx: &mut VisualTestContext) -> bool {
        view.read_with(cx, |v, _| v.switch_busy.is_none() && !v.switch_reading)
    }

    /// The status row shows a stopped yard with Start, which runs `up`
    /// on the yard's home: its socket minus `yard.sock`. Once the yard
    /// answers, the status row shows Running with Stop. Nothing of the
    /// switch acts as anyone: no `--actor` anywhere.
    #[gpui::test]
    fn the_status_row_shows_a_stopped_yard_and_start_runs_up_on_its_home(cx: &mut TestAppContext) {
        use crate::setup::standin;

        let dir = tempfile::tempdir().unwrap();
        let socket = dir.path().join("second/yard.sock");
        std::fs::create_dir_all(socket.parent().unwrap()).unwrap();
        let file = dir.path().join("footplate/settings.json");
        Settings {
            yards: vec![settings::Yard::near("second", socket.to_str().unwrap())],
            open: "second".to_string(),
            ..Settings::default()
        }
        .write(&file)
        .unwrap();
        let env = Env {
            socket: dir.path().join("yard.sock"),
            ..Env::default()
        };
        let (view, cx) = opened_at(env, &file, cx);
        let (means, program, _) = stand_in_means(dir.path(), true);
        standin::answers(&program, "doctor", 0, &standin::doctor_ready());
        standin::answers(&program, "status.1", 0, &standin::status(false, false));
        standin::answers(&program, "status", 0, &standin::status(true, false));
        standin::answers(&program, "up.1", 0, &json!({"up": true, "parts": []}));
        view.update(cx, |v, _| v.means = means);
        view.update(cx, |v, cx| v.refresh_switch(cx));
        wait(cx, "the stopped yard read", |cx| {
            settled(&view, cx) && view.read_with(cx, |v, _| v.switch_status.is_some())
        });
        assert!(drawn(cx, "switch start"));
        assert!(!drawn(cx, "switch stop"));
        assert!(view.read_with(cx, |v, _| v.yard_is_stopped()));
        // "Start at login" is a switch of the settings, off here.
        click_on(cx, "settings");
        click_on(cx, "settings section yards");
        assert!(drawn(cx, "login off"));
        assert!(drawn(cx, "login on"));
        click_on(cx, "settings");

        click_on(cx, "switch start");
        wait(cx, "up run", |cx| {
            settled(&view, cx)
                && standin::calls(&program)
                    .iter()
                    .any(|call| call.starts_with("[up]"))
        });
        let home = dir.path().join("second");
        assert!(
            standin::calls(&program)
                .iter()
                .any(|call| call == &format!("[up] [--json] [--home] [{}]", home.display())),
            "{:?}",
            standin::calls(&program)
        );
        assert!(
            standin::calls(&program)
                .iter()
                .all(|call| !call.contains("--actor")),
            "{:?}",
            standin::calls(&program)
        );

        // The yard answers: Running with Stop. (What was drawn stays
        // drawn to the tests: gpui keeps every selector until the same
        // one paints again. So tests say what is there, and never what
        // went away.)
        let yard = Yard::start_at(&socket);
        a_yard_of_jo(&yard);
        wait(cx, "the yard running", |cx| {
            settled(&view, cx) && view.read_with(cx, |v, _| v.down.is_none() && v.model.is_some())
        });
        assert!(drawn(cx, "switch stop"));
    }

    /// The status row holds one line in the mode's list at the
    /// narrowest window, with its action on its row, inside the list's
    /// edge.
    fn status_row_holds_in(mode: Mode, cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let socket = dir.path().join("second/yard.sock");
        std::fs::create_dir_all(socket.parent().unwrap()).unwrap();
        let yard = Yard::start_at(&socket);
        a_yard_of_jo(&yard);
        let file = dir.path().join("footplate/settings.json");
        Settings {
            yards: vec![settings::Yard::near("second", socket.to_str().unwrap())],
            open: "second".to_string(),
            ..Settings::default()
        }
        .write(&file)
        .unwrap();
        let env = Env {
            socket: dir.path().join("yard.sock"),
            ..Env::default()
        };
        let (view, cx) = opened_at(env, &file, cx);
        wait(cx, "the yard running", |cx| {
            settled(&view, cx) && view.read_with(cx, |v, _| v.down.is_none() && v.model.is_some())
        });
        match mode {
            Mode::Chat => to_chat(&view, cx),
            Mode::Decisions => to_decisions(&view, cx),
            Mode::Timetable => to_timetable(&view, cx),
        }
        cx.run_until_parked();
        // Tests fetch no yardr: say it is there, so the row is Running
        // with Stop, as on a machine with one.
        view.update(cx, |v, _| {
            v.switch_program = Some(dir.path().join("yardr"));
            v.switch_note = None;
        });
        // The narrowest window the application opens (main.rs).
        cx.simulate_resize(gpui::size(px(616.), px(360.)));
        let state = bounds_of(cx, "switch state");
        let button = bounds_of(cx, "switch stop");
        let rows = bounds_of(cx, "rows");
        assert!(
            state.size.height <= button.size.height + px(2.),
            "the status row wraps in {}: {state:?} against {button:?}",
            mode.name()
        );
        assert!(
            button.top() >= state.top() - px(1.) && button.bottom() <= state.bottom() + px(1.),
            "Stop stands off the status row in {}: {state:?} {button:?}",
            mode.name()
        );
        assert!(
            button.right() <= rows.right() + px(1.),
            "Stop runs past the list in {}: {button:?} past {rows:?}",
            mode.name()
        );
    }

    /// The status row holds at the narrowest window in chat: one line,
    /// with Stop inside the list's edge.
    #[gpui::test]
    fn the_status_row_holds_in_chat_at_the_narrowest_window(cx: &mut TestAppContext) {
        status_row_holds_in(Mode::Chat, cx);
    }

